export interface MedicineData {
  name: string;
  description: string;
  uses: string[];
  dosage: string;
  sideEffects: string[];
  warnings: string;
}

export interface Reminder {
  id: string;
  medicineName: string;
  time: string; // HH:mm format
  active: boolean;
}

export enum AppView {
  HOME = 'HOME',
  SCANNER = 'SCANNER',
  REMINDERS = 'REMINDERS',
  PROFILE = 'PROFILE'
}

export interface AnalysisState {
  loading: boolean;
  data: MedicineData | null;
  error: string | null;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { MedicineData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MEDICINE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING, description: "The name of the medicine found in the image." },
    description: { type: Type.STRING, description: "A brief summary of what the medicine is." },
    uses: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "List of common ailments this medicine treats."
    },
    dosage: { type: Type.STRING, description: "General dosage guidelines (add disclaimer)." },
    sideEffects: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "List of potential side effects."
    },
    warnings: { type: Type.STRING, description: "Critical warnings or contraindications." }
  },
  required: ["name", "description", "uses", "dosage", "sideEffects", "warnings"]
};

export const analyzeMedicineImage = async (base64Image: string): Promise<MedicineData> => {
  try {
    // Strip the data:image/jpeg;base64, prefix if present
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: cleanBase64
            }
          },
          {
            text: "Analyze this medicine image. Provide the name, description, uses, dosage instructions, side effects, and warnings. Be accurate and helpful."
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: MEDICINE_SCHEMA,
        systemInstruction: "You are an expert pharmacist AI assistant. Identify the medicine from the image packaging or pill. Provide accurate medical information. Always include a disclaimer that this is AI advice and a doctor should be consulted."
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as MedicineData;
    } else {
      throw new Error("No data returned from AI");
    }
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const getHealthTip = async (): Promise<string> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: "Give me one short, random, interesting daily health tip in 15 words or less."
        });
        return response.text || "Drink water and stay hydrated!";
    } catch (e) {
        return "Stay active and eat healthy!";
    }
}

