import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData } from '../types';

interface ScannerProps {
  onScanComplete: (data: MedicineData) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScanComplete, onError }) => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Create preview
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImagePreview(base64);
      setAnalyzing(true);
      try {
        const data = await analyzeMedicineImage(base64);
        onScanComplete(data);
      } catch (err) {
        onError("Could not analyze image. Please try again with a clearer photo.");
        setImagePreview(null);
      } finally {
        setAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  }, [onScanComplete, onError]);

  const triggerCamera = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  return (
    <div className="flex flex-col items-center justify-center w-full min-h-[50vh]">
      <input
        type="file"
        accept="image/*"
        capture="environment"
        ref={fileInputRef}
        onChange={handleFileChange}
        className="hidden"
      />

      {analyzing ? (
        <div className="text-center p-8 bg-white rounded-3xl shadow-xl w-full max-w-sm mx-4">
            {imagePreview && (
                <img src={imagePreview} alt="Scanning" className="w-32 h-32 object-cover rounded-full mx-auto mb-6 border-4 border-teal-100 animate-pulse" />
            )}
            <h3 className="text-xl font-bold text-teal-700 mb-2">Analyzing...</h3>
            <p className="text-gray-500">Identifying medicine and consulting AI...</p>
            <div className="mt-6 w-full bg-gray-200 rounded-full h-2.5">
              <div className="bg-teal-600 h-2.5 rounded-full animate-[width_2s_ease-in-out_infinite]" style={{width: '70%'}}></div>
            </div>
        </div>
      ) : (
        <div className="text-center space-y-8 animate-fade-in-up">
           <div className="relative group cursor-pointer" onClick={triggerCamera}>
              <div className="absolute -inset-1 bg-gradient-to-r from-teal-400 to-blue-500 rounded-full blur opacity-25 group-hover:opacity-75 transition duration-1000 group-hover:duration-200"></div>
              <button className="relative w-48 h-48 bg-white rounded-full flex flex-col items-center justify-center shadow-2xl border-4 border-teal-50 hover:scale-105 transition-transform">
                <svg className="w-16 h-16 text-teal-500 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                <span className="font-bold text-gray-700 text-lg">Tap to Scan</span>
              </button>
           </div>

           <p className="text-gray-500 max-w-xs mx-auto">
             Take a clear photo of the medicine strip, bottle, or tablet to identify it instantly.
           </p>
        </div>
      )}
    </div>
  );
};

export default Scanner;

import React, { useState } from 'react';
import { Reminder } from '../types';

interface RemindersProps {
  reminders: Reminder[];
  addReminder: (r: Reminder) => void;
  deleteReminder: (id: string) => void;
  toggleReminder: (id: string) => void;
}

const Reminders: React.FC<RemindersProps> = ({ reminders, addReminder, deleteReminder, toggleReminder }) => {
  const [name, setName] = useState('');
  const [time, setTime] = useState('');
  const [showForm, setShowForm] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !time) return;

    addReminder({
      id: Date.now().toString(),
      medicineName: name,
      time: time,
      active: true
    });
    setName('');
    setTime('');
    setShowForm(false);
  };

  return (
    <div className="p-4 space-y-6 pb-24">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">My Alarms</h2>
        <button 
            onClick={() => setShowForm(!showForm)}
            className="bg-teal-600 text-white px-4 py-2 rounded-full shadow-lg hover:bg-teal-700 font-medium text-sm flex items-center"
        >
            <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            Add
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-4 rounded-xl shadow-md border border-gray-100 animate-fade-in-down">
            <div className="mb-3">
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Medicine Name</label>
                <input 
                    type="text" 
                    value={name} 
                    onChange={(e) => setName(e.target.value)} 
                    placeholder="e.g. Paracetamol"
                    className="w-full p-2 rounded-lg bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500"
                />
            </div>
            <div className="mb-4">
                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Time</label>
                <input 
                    type="time" 
                    value={time} 
                    onChange={(e) => setTime(e.target.value)} 
                    className="w-full p-2 rounded-lg bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500"
                />
            </div>
            <button type="submit" className="w-full bg-teal-600 text-white py-2 rounded-lg font-bold shadow hover:bg-teal-700">Set Alarm</button>
        </form>
      )}

      {reminders.length === 0 ? (
        <div className="text-center py-10 text-gray-400">
            <svg className="w-16 h-16 mx-auto mb-3 opacity-30" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <p>No alarms set yet.</p>
        </div>
      ) : (
        <div className="space-y-3">
            {reminders.map(rem => (
                <div key={rem.id} className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center">
                    <div className="flex items-center space-x-4">
                        <div className={`w-12 h-12 rounded-full flex items-center justify-center ${rem.active ? 'bg-teal-100 text-teal-600' : 'bg-gray-100 text-gray-400'}`}>
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        </div>
                        <div>
                            <h3 className={`font-bold ${rem.active ? 'text-gray-800' : 'text-gray-400'}`}>{rem.medicineName}</h3>
                            <p className="text-sm text-gray-500">{rem.time}</p>
                        </div>
                    </div>

                    <div className="flex items-center space-x-3">
                        <button 
                            onClick={() => toggleReminder(rem.id)}
                            className={`w-10 h-6 rounded-full p-1 transition-colors ${rem.active ? 'bg-teal-500' : 'bg-gray-300'}`}
                        >
                            <div className={`bg-white w-4 h-4 rounded-full shadow-md transform transition-transform ${rem.active ? 'translate-x-4' : ''}`}></div>
                        </button>
                        <button onClick={() => deleteReminder(rem.id)} className="text-red-400 hover:text-red-600">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                    </div>
                </div>
            ))}
        </div>
      )}
    </div>
  );
};

export default Reminders;

import React, { useState, useEffect } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import PremiumModal from './components/PremiumModal';
import { MedicineData, AppView, Reminder } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [isPremium, setIsPremium] = useState(false);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");

  // Load state from local storage on mount
  useEffect(() => {
    const savedPremium = localStorage.getItem('mediScan_premium');
    if (savedPremium === 'true') setIsPremium(true);

    const savedReminders = localStorage.getItem('mediScan_reminders');
    if (savedReminders) setReminders(JSON.parse(savedReminders));

    // Check for alarms every minute
    const interval = setInterval(checkAlarms, 60000);

    // Get a health tip
    getHealthTip().then(setHealthTip);

    return () => clearInterval(interval);
  }, []);

  // Save reminders whenever they change
  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  const checkAlarms = () => {
    const now = new Date();
    const currentTime = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

    reminders.forEach(rem => {
      if (rem.active && rem.time === currentTime) {
        // In a real app we'd use Notifications API, here we use alert/toast
        alert(`⏰ Time to take your medicine: ${rem.medicineName}`);
      }
    });
  };

  const handleUpgrade = () => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    setShowPremiumModal(false);
  };

  const addReminder = (r: Reminder) => {
    setReminders([...reminders, r]);
  };

  const deleteReminder = (id: string) => {
    setReminders(reminders.filter(r => r.id !== id));
  };

  const toggleReminder = (id: string) => {
    setReminders(reminders.map(r => r.id === id ? { ...r, active: !r.active } : r));
  };

  const handleScanComplete = (data: MedicineData) => {
    setScannedData(data);
  };

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          isPremium={isPremium} 
          onOpenPremium={() => setShowPremiumModal(true)}
          onClose={() => setScannedData(null)}
        />
      );
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="p-6">
            <header className="mb-8">
               <h1 className="text-3xl font-bold text-gray-900">MediScan <span className="text-teal-600">AI</span></h1>
               <p className="text-gray-500 text-sm mt-1">Your pocket pharmacist</p>
               {healthTip && (
                 <div className="mt-4 p-3 bg-teal-50 border border-teal-100 rounded-lg text-xs text-teal-800 flex items-start">
                    <span className="mr-2 text-lg">💡</span>
                    <span>{healthTip}</span>
                 </div>
               )}
            </header>
            <Scanner 
              onScanComplete={handleScanComplete} 
              onError={(msg) => alert(msg)} 
            />

            {!isPremium && (
                <div 
                    onClick={() => setShowPremiumModal(true)}
                    className="mt-8 bg-gradient-to-r from-gray-900 to-gray-800 text-white p-5 rounded-2xl shadow-xl flex justify-between items-center cursor-pointer transform transition hover:scale-[1.02]"
                >
                    <div>
                        <h3 className="font-bold text-lg">Go Premium</h3>
                        <p className="text-xs text-gray-400">Unlock Side Effects & More</p>
                    </div>
                    <div className="bg-yellow-400 text-black px-3 py-1 rounded-lg font-bold text-sm">₹49</div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return (
          <Reminders 
            reminders={reminders} 
            addReminder={addReminder} 
            deleteReminder={deleteReminder}
            toggleReminder={toggleReminder}
          />
        );
      default:
        return <div>View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto bg-gray-50 min-h-screen relative shadow-2xl overflow-hidden">

      {/* Main Content Area */}
      <main className="min-h-screen">
        {renderContent()}
      </main>

      {/* Navigation Bar (Bottom) */}
      {!scannedData && (
        <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-200 shadow-lg px-6 py-3 flex justify-around items-center z-40">
            <button 
                onClick={() => setCurrentView(AppView.HOME)}
                className={`flex flex-col items-center space-y-1 ${currentView === AppView.HOME ? 'text-teal-600' : 'text-gray-400'}`}
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
                <span className="text-xs font-medium">Scan</span>
            </button>

            <button 
                onClick={() => setCurrentView(AppView.REMINDERS)}
                className={`flex flex-col items-center space-y-1 ${currentView === AppView.REMINDERS ? 'text-teal-600' : 'text-gray-400'}`}
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <span className="text-xs font-medium">Alarms</span>
            </button>

            <button 
                onClick={() => setShowPremiumModal(true)}
                className={`flex flex-col items-center space-y-1 ${isPremium ? 'text-yellow-500' : 'text-gray-400'}`}
            >
                 <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span className="text-xs font-medium">{isPremium ? 'Premium' : 'Upgrade'}</span>
            </button>
        </nav>
      )}

      {/* Modals */}
      <PremiumModal 
        isOpen={showPremiumModal} 
        onClose={() => setShowPremiumModal(false)} 
        onUpgrade={handleUpgrade}
      />
    </div>
  );
};

export default App;

import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData } from '../types';

interface ScannerProps {
  onScanComplete: (data: MedicineData) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScanComplete, onError }) => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Create preview
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImagePreview(base64);
      setAnalyzing(true);
      try {
        const data = await analyzeMedicineImage(base64);
        onScanComplete(data);
