import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile } from '../types';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ data, profile, isPremium, onOpenPremium, onClose }) => {
  const [speaking, setSpeaking] = useState(false);

  useEffect(() => {
    // Cancel speech when component unmounts
    return () => {
        window.speechSynthesis.cancel();
    }
  }, []);

  const toggleSpeech = () => {
    if (speaking) {
        window.speechSynthesis.cancel();
        setSpeaking(false);
    } else {
        const textToRead = `
            ${data.name}. 
            ${data.simpleExplanation}. 
            ${data.ageAdvice}. 
            ${data.pregnancyWarning ? 'Warning: ' + data.pregnancyWarning : ''}
        `;
        const utterance = new SpeechSynthesisUtterance(textToRead);

        // Try to set language
        if (profile?.language === 'hindi') {
            utterance.lang = 'hi-IN';
        } else {
            utterance.lang = 'en-US';
        }

        utterance.onend = () => setSpeaking(false);
        window.speechSynthesis.speak(utterance);
        setSpeaking(true);
    }
  };

  return (
    <div className="pb-24">
      <div className="bg-white rounded-t-3xl shadow-xl border border-gray-100 overflow-hidden min-h-screen">

        {/* Header */}
        <div className="bg-teal-600 p-6 text-white relative">
            <button onClick={onClose} className="absolute top-6 right-6 p-2 bg-teal-700 rounded-full hover:bg-teal-800 z-10">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
            <div className="pr-10">
                <h2 className="text-2xl font-bold">{data.name}</h2>
                <p className="text-teal-100 mt-1 text-sm opacity-90">{data.description}</p>
            </div>

            {/* Play Button */}
            <button 
                onClick={toggleSpeech}
                className="absolute -bottom-6 right-6 w-14 h-14 bg-yellow-400 rounded-full shadow-lg flex items-center justify-center text-black hover:scale-110 transition-transform"
            >
                {speaking ? (
                    <div className="flex space-x-1 items-center h-4">
                        <div className="w-1 h-4 bg-black animate-bounce" style={{animationDelay: '0s'}}></div>
                        <div className="w-1 h-4 bg-black animate-bounce" style={{animationDelay: '0.1s'}}></div>
                        <div className="w-1 h-4 bg-black animate-bounce" style={{animationDelay: '0.2s'}}></div>
                    </div>
                ) : (
                    <svg className="w-7 h-7 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                )}
            </button>
        </div>

        <div className="p-6 pt-10 space-y-6">

            {/* CRITICAL ALERTS */}
            {(data.pregnancyWarning || data.breastfeedingWarning) && (
                <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg animate-pulse">
                    <div className="flex items-start">
                        <div className="flex-shrink-0">
                            <svg className="h-5 w-5 text-red-500" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                            </svg>
                        </div>
                        <div className="ml-3">
                            <h3 className="text-sm font-medium text-red-800">Critical Safety Alert</h3>
                            {data.pregnancyWarning && <p className="text-sm text-red-700 mt-1">🤰 {data.pregnancyWarning}</p>}
                            {data.breastfeedingWarning && <p className="text-sm text-red-700 mt-1">🤱 {data.breastfeedingWarning}</p>}
