import React, { useState } from 'react';
import { Reminder, FoodContext, RepeatType, SoundType } from '../types';

interface RemindersProps {
  reminders: Reminder[];
  addReminder: (r: Reminder) => void;
  deleteReminder: (id: string) => void;
  toggleReminder: (id: string) => void;
}

const Reminders: React.FC<RemindersProps> = ({ reminders, addReminder, deleteReminder, toggleReminder }) => {
  const [showForm, setShowForm] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [dose, setDose] = useState('');
  const [time, setTime] = useState('');
  const [foodContext, setFoodContext] = useState<FoodContext>('after_food');
  const [repeat, setRepeat] = useState<RepeatType>('daily');
  const [customDays, setCustomDays] = useState<number[]>([]); // 0-6
  const [soundType, setSoundType] = useState<SoundType>('default');

  const DAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  const toggleDay = (idx: number) => {
      setCustomDays(prev => prev.includes(idx) ? prev.filter(d => d !== idx) : [...prev, idx]);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !time || !dose) return;

    // Validation for custom days
    if (repeat === 'custom' && customDays.length === 0) {
        alert("Please select at least one day for custom repeat.");
        return;
    }

    addReminder({
      id: Date.now().toString(),
      medicineName: name,
      dose: dose,
      time: time,
      foodContext: foodContext,
      repeat: repeat,
      customDays: repeat === 'custom' ? customDays : [],
      soundType: soundType,
      active: true,
      snoozedUntil: null,
      createdAt: Date.now()
    });

    // Reset Form
    setName('');
    setDose('');
    setTime('');
    setFoodContext('after_food');
    setRepeat('daily');
    setCustomDays([]);
    setSoundType('default');
    setShowForm(false);
  };

  return (
    <div className="p-4 space-y-6 pb-24">

      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
            <h2 className="text-2xl font-bold text-gray-900">My Alarms</h2>
            <p className="text-gray-400 text-xs">Manage your medication schedule</p>
        </div>
        <button 
            onClick={() => setShowForm(!showForm)}
            className="bg-black text-white px-5 py-2.5 rounded-full shadow-lg hover:bg-gray-800 font-bold text-sm flex items-center transition-all"
        >
            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            Add Alarm
        </button>
      </div>

      {/* Add Alarm Form */}
      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-5 rounded-2xl shadow-xl border border-gray-100 animate-fade-in-down space-y-4">

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Medicine Name</label>
                    <input 
                        type="text" 
                        value={name} 
                        onChange={(e) => setName(e.target.value)} 
                        placeholder="e.g. Paracetamol"
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Dose</label>
                    <input 
                        type="text" 
                        value={dose} 
                        onChange={(e) => setDose(e.target.value)} 
                        placeholder="e.g. 1 Tablet"
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm"
                    />
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Time</label>
                    <input 
                        type="time" 
                        value={time} 
                        onChange={(e) => setTime(e.target.value)} 
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm font-mono"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">When to take?</label>
                    <select 
                        value={foodContext}
                        onChange={(e) => setFoodContext(e.target.value as FoodContext)}
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm appearance-none"
                    >
                        <option value="before_food">Before Food 🍎</option>
                        <option value="after_food">After Food 🥣</option>
                        <option value="empty_stomach">Empty Stomach 🚫</option>
                        <option value="any">Anytime 🤷</option>
                    </select>
                </div>
            </div>

            {/* Repeat Section */}
            <div>
                 <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Repeat Schedule</label>
                 <div className="flex space-x-2 mb-3">
                     {['daily', 'alternate', 'custom'].map((r) => (
                         <button
                            key={r}
                            type="button"
                            onClick={() => setRepeat(r as RepeatType)}
                            className={`flex-1 py-2 text-xs font-bold rounded-lg capitalize border ${repeat === r ? 'bg-teal-600 text-white border-teal-600' : 'bg-white text-gray-600 border-gray-200'}`}
                         >
                             {r}
                         </button>
                     ))}
                 </div>

                 {repeat === 'custom' && (
                     <div className="flex justify-between">
                         {DAYS.map((d, i) => (
                             <button
                                key={i}
                                type="button"
                                onClick={() => toggleDay(i)}
                                className={`w-8 h-8 rounded-full text-xs font-bold flex items-center justify-center transition-colors ${customDays.includes(i) ? 'bg-teal-500 text-white' : 'bg-gray-100 text-gray-400'}`}
                             >
                                 {d}
                             </button>
                         ))}
                     </div>
                 )}
            </div>

            {/* Sound Section */}
            <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Alarm Sound</label>
                <div className="grid grid-cols-2 gap-2">
                     <button type="button" onClick={() => setSoundType('default')} className={`py-2 text-xs rounded-lg border ${soundType === 'default' ? 'bg-blue-50 border-blue-500 text-blue-700' : 'border-gray-200'}`}>🔔 Default</button>
                     <button type="button" onClick={() => setSoundType('soft')} className={`py-2 text-xs rounded-lg border ${soundType === 'soft' ? 'bg-purple-50 border-purple-500 text-purple-700' : 'border-gray-200'}`}>🌙 Soft (Night)</button>
                     <button type="button" onClick={() => setSoundType('loud')} className={`py-2 text-xs rounded-lg border ${soundType === 'loud' ? 'bg-red-50 border-red-500 text-red-700' : 'border-gray-200'}`}>📢 Loud</button>
                     <button type="button" onClick={() => setSoundType('voice')} className={`py-2 text-xs rounded-lg border ${soundType === 'voice' ? 'bg-green-50 border-green-500 text-green-700' : 'border-gray-200'}`}>🗣️ Voice</button>
                </div>
            </div>

            <button type="submit" className="w-full bg-teal-600 text-white py-3.5 rounded-xl font-bold shadow-lg hover:bg-teal-700 mt-2">
                Set Alarm
            </button>
        </form>
      )}

      {/* Alarm List */}
      <div className="space-y-4">
            {reminders.map(rem => (
                <div key={rem.id} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden group">
                    {/* Active Indicator Strip */}
                    <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${rem.active ? 'bg-teal-500' : 'bg-gray-300'}`}></div>

                    <div className="flex justify-between items-start pl-3">
                        <div>
                            <div className="flex items-center space-x-2 mb-1">
                                <h3 className={`font-bold text-lg ${rem.active ? 'text-gray-800' : 'text-gray-400'}`}>{rem.medicineName}</h3>
                                <span className="text-xs font-semibold px-2 py-0.5 bg-gray-100 text-gray-500 rounded">{rem.dose}</span>
                            </div>

                            <p className="text-2xl font-mono font-bold text-gray-700">{rem.time}</p>

                            <div className="flex space-x-2 mt-2">
                                <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-md ${rem.active ? 'bg-orange-50 text-orange-600' : 'bg-gray-50 text-gray-400'}`}>
                                    {rem.foodContext === 'before_food' ? 'Before Food' : rem.foodContext === 'after_food' ? 'After Food' : rem.foodContext === 'empty_stomach' ? 'Empty Stomach' : 'Anytime'}
                                </span>
                                <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-md bg-blue-50 text-blue-600">
                                    {rem.repeat === 'custom' ? 'Custom Days' : rem.repeat}
                                </span>
                            </div>
                        </div>

                        <div className="flex flex-col items-end space-y-3">
                             <button 
                                onClick={() => toggleReminder(rem.id)}
                                className={`w-12 h-7 rounded-full p-1 transition-colors duration-300 ${rem.active ? 'bg-teal-500' : 'bg-gray-300'}`}
                            >
                                <div className={`bg-white w-5 h-5 rounded-full shadow-md transform transition-transform duration-300 ${rem.active ? 'translate-x-5' : ''}`}></div>
                            </button>

                            <button onClick={() => deleteReminder(rem.id)} className="text-red-300 hover:text-red-500 p-1">
                                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            </button>
                        </div>
                    </div>
                </div>
            ))}

            {reminders.length === 0 && (
                <div className="text-center py-12 text-gray-400">
                    <p>No alarms set yet. Tap "Add Alarm" to start.</p>
                </div>
            )}
      </div>
    </div>
  );
};

