import React, { useState } from 'react';
import { Reminder, FoodContext, RepeatType, SoundType, VoiceTone } from '../types';

interface RemindersProps {
  reminders: Reminder[];
  addReminder: (r: Reminder) => void;
  deleteReminder: (id: string) => void;
  toggleReminder: (id: string) => void;
}

const Reminders: React.FC<RemindersProps> = ({ reminders, addReminder, deleteReminder, toggleReminder }) => {
  const [showForm, setShowForm] = useState(false);

  // Form State
  const [name, setName] = useState('');
  const [dose, setDose] = useState('');
  const [time, setTime] = useState('');
  const [foodContext, setFoodContext] = useState<FoodContext>('after_food');
  const [repeat, setRepeat] = useState<RepeatType>('daily');
  const [customDays, setCustomDays] = useState<number[]>([]); // 0-6
  const [soundType, setSoundType] = useState<SoundType>('default');
  const [voiceTone, setVoiceTone] = useState<VoiceTone>('normal');

  const DAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  const toggleDay = (idx: number) => {
      setCustomDays(prev => prev.includes(idx) ? prev.filter(d => d !== idx) : [...prev, idx]);
  };

  const previewSound = (type: SoundType, tone?: VoiceTone) => {
      // Logic to preview sound immediately
      if (type === 'voice') {
          window.speechSynthesis.cancel();
          let text = "It's time to take your medicine.";
          if (tone === 'strict') text = "Please take your medicine now. Don't skip this dose.";
          if (tone === 'friendly') text = "Hey! Don't forget your medicine.";
          if (tone === 'hindi') text = "Dawai lene ka time ho gaya hai.";

          const u = new SpeechSynthesisUtterance(text);
          if (tone === 'hindi') u.lang = 'hi-IN';
          window.speechSynthesis.speak(u);
      } else {
          // Play a quick beep
           try {
               const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
               const ctx = new AudioContext();
               const osc = ctx.createOscillator();
               const gain = ctx.createGain();
               osc.connect(gain);
               gain.connect(ctx.destination);

               if (type === 'soft') {
                   osc.type = 'sine'; osc.frequency.setValueAtTime(300, ctx.currentTime);
               } else if (type === 'loud') {
                   osc.type = 'sawtooth'; osc.frequency.setValueAtTime(800, ctx.currentTime);
               } else {
                   osc.type = 'square'; osc.frequency.setValueAtTime(440, ctx.currentTime);
               }
               osc.start();
               osc.stop(ctx.currentTime + 0.3);
           } catch (e) {}
      }
  };

  const handleSoundSelect = (type: SoundType) => {
      setSoundType(type);
      previewSound(type, voiceTone);
  };

  const handleToneSelect = (tone: VoiceTone) => {
      setVoiceTone(tone);
      previewSound('voice', tone);
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !time || !dose) return;

    if (repeat === 'custom' && customDays.length === 0) {
        alert("Please select at least one day for custom repeat.");
        return;
    }

    addReminder({
      id: Date.now().toString(),
      medicineName: name,
      dose: dose,
      time: time,
      foodContext: foodContext,
      repeat: repeat,
      customDays: repeat === 'custom' ? customDays : [],
      soundType: soundType,
      voiceTone: soundType === 'voice' ? voiceTone : undefined,
      active: true,
      snoozedUntil: null,
      createdAt: Date.now()
    });

    // Reset Form
    setName('');
    setDose('');
    setTime('');
    setFoodContext('after_food');
    setRepeat('daily');
    setCustomDays([]);
    setSoundType('default');
    setVoiceTone('normal');
    setShowForm(false);
  };

  return (
    <div className="p-4 space-y-6 pb-24">

      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
            <h2 className="text-2xl font-bold text-gray-900">My Alarms</h2>
            <p className="text-gray-400 text-xs">Manage your medication schedule</p>
        </div>
        <button 
            onClick={() => setShowForm(!showForm)}
            className="bg-black text-white px-5 py-2.5 rounded-full shadow-lg hover:bg-gray-800 font-bold text-sm flex items-center transition-all"
        >
            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            Add Alarm
        </button>
      </div>

      {/* Add Alarm Form */}
      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-5 rounded-2xl shadow-xl border border-gray-100 animate-fade-in-down space-y-4">

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Medicine Name</label>
                    <input 
                        type="text" 
                        value={name} 
                        onChange={(e) => setName(e.target.value)} 
                        placeholder="e.g. Paracetamol"
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Dose</label>
                    <input 
                        type="text" 
                        value={dose} 
                        onChange={(e) => setDose(e.target.value)} 
                        placeholder="e.g. 1 Tablet"
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm"
                    />
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Time</label>
                    <input 
                        type="time" 
                        value={time} 
                        onChange={(e) => setTime(e.target.value)} 
                        required
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm font-mono"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">When to take?</label>
                    <select 
                        value={foodContext}
                        onChange={(e) => setFoodContext(e.target.value as FoodContext)}
                        className="w-full p-3 rounded-xl bg-gray-50 border border-gray-200 focus:outline-none focus:border-teal-500 text-sm appearance-none"
                    >
                        <option value="before_food">Before Food 🍎</option>
                        <option value="after_food">After Food 🥣</option>
                        <option value="empty_stomach">Empty Stomach 🚫</option>
                        <option value="any">Anytime 🤷</option>
                    </select>
                </div>
            </div>

            {/* Repeat Section */}
            <div>
                 <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Repeat Schedule</label>
                 <div className="flex space-x-2 mb-3">
                     {['daily', 'alternate', 'custom'].map((r) => (
                         <button
                            key={r}
                            type="button"
                            onClick={() => setRepeat(r as RepeatType)}
                            className={`flex-1 py-2 text-xs font-bold rounded-lg capitalize border ${repeat === r ? 'bg-teal-600 text-white border-teal-600' : 'bg-white text-gray-600 border-gray-200'}`}
                         >
                             {r}
                         </button>
                     ))}
                 </div>

                 {repeat === 'custom' && (
                     <div className="flex justify-between">
                         {DAYS.map((d, i) => (
                             <button
                                key={i}
                                type="button"
                                onClick={() => toggleDay(i)}
                                className={`w-8 h-8 rounded-full text-xs font-bold flex items-center justify-center transition-colors ${customDays.includes(i) ? 'bg-teal-500 text-white' : 'bg-gray-100 text-gray-400'}`}
                             >
                                 {d}
                             </button>
                         ))}
                     </div>
                 )}
            </div>

            {/* Sound Section */}
            <div>
