                          {(['english', 'hindi', 'hinglish'] as Language[]).map(l => (
                              <button
                                  key={l}
                                  onClick={() => setLanguage(l)}
                                  className={`py-2 px-1 rounded-lg text-sm font-medium capitalize border ${language === l ? 'bg-teal-600 text-white border-teal-600' : 'bg-white text-gray-600 border-gray-200'}`}
                              >
                                  {l}
                              </button>
                          ))}
                      </div>
                  </div>

                  {/* Age Group */}
                  <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Age Group</label>
                      <div className="grid grid-cols-3 gap-2">
                          <button onClick={() => setAgeGroup('child')} className={`py-3 rounded-xl border flex flex-col items-center justify-center ${ageGroup === 'child' ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-gray-200'}`}>
                              <span className="text-xl mb-1">👶</span>
                              <span className="text-xs font-bold">Child</span>
                          </button>
                          <button onClick={() => setAgeGroup('adult')} className={`py-3 rounded-xl border flex flex-col items-center justify-center ${ageGroup === 'adult' ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-gray-200'}`}>
                              <span className="text-xl mb-1">🧑</span>
                              <span className="text-xs font-bold">Adult</span>
                          </button>
                          <button onClick={() => setAgeGroup('senior')} className={`py-3 rounded-xl border flex flex-col items-center justify-center ${ageGroup === 'senior' ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-gray-200'}`}>
                              <span className="text-xl mb-1">👴</span>
                              <span className="text-xs font-bold">Senior</span>
                          </button>
                      </div>
                  </div>

                  {/* Gender */}
                  <div>
                      <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Gender</label>
