                              Male
                          </button>
                          <button onClick={() => setGender('female')} className={`py-2 rounded-lg font-medium border ${gender === 'female' ? 'bg-pink-500 text-white border-pink-500' : 'text-gray-600 border-gray-200'}`}>
                              Female
                          </button>
                      </div>
                  </div>

                  {/* Pregnancy/Breastfeeding Checks (Only for Female) */}
                  {gender === 'female' && (
                      <div className="bg-pink-50 p-4 rounded-xl space-y-3">
                          <label className="flex items-center space-x-3 cursor-pointer">
                              <input 
                                  type="checkbox" 
                                  checked={isPregnant} 
                                  onChange={(e) => setIsPregnant(e.target.checked)}
                                  className="w-5 h-5 text-pink-500 rounded focus:ring-pink-500" 
                              />
                              <span className="text-gray-700 font-medium">Pregnant 🤰</span>
                          </label>
                          <label className="flex items-center space-x-3 cursor-pointer">
                              <input 
                                  type="checkbox" 
                                  checked={isBreastfeeding} 
                                  onChange={(e) => setIsBreastfeeding(e.target.checked)}
                                  className="w-5 h-5 text-pink-500 rounded focus:ring-pink-500" 
                              />
                              <span className="text-gray-700 font-medium">Breastfeeding 🤱</span>
                          </label>
                      </div>
                  )}

                  <div className="pt-2">
                    <button 
                        onClick={startAnalysis}
                        className="w-full bg-black text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:scale-[1.02] transition-transform flex items-center justify-center"
                    >
                        <span>Analyze Medicine</span>
                        <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                    </button>
                    <button onClick={() => { setImagePreview(null); setShowForm(false); }} className="w-full text-center py-3 text-gray-500 text-sm mt-2">
                        Cancel
                    </button>
                  </div>
              </div>
          </div>
      )
  }

  return (
    <div className="flex flex-col items-center justify-center w-full min-h-[50vh]">
      <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} onChange={handleFileChange} className="hidden" />
      <input type="file" accept="image/*" ref={galleryInputRef} onChange={handleFileChange} className="hidden" />

      {analyzing ? (
        <div className="text-center p-8 bg-white rounded-3xl shadow-xl w-full max-w-sm mx-4">
            {imagePreview && (
                <img src={imagePreview} alt="Scanning" className="w-32 h-32 object-cover rounded-full mx-auto mb-6 border-4 border-teal-100 animate-pulse" />
            )}
            <h3 className="text-xl font-bold text-teal-700 mb-2">Consulting AI...</h3>
            <p className="text-gray-500 text-sm">Checking dosage for {ageGroup}...</p>
            {isPregnant && <p className="text-pink-500 text-xs mt-1 animate-pulse">Checking pregnancy safety...</p>}

            <div className="mt-6 w-full bg-gray-200 rounded-full h-2.5">
              <div className="bg-teal-600 h-2.5 rounded-full animate-[width_2s_ease-in-out_infinite]" style={{width: '70%'}}></div>
            </div>
        </div>
      ) : (
        <div className="text-center space-y-6 w-full max-w-xs animate-fade-in-up">

           {/* Soft Share Banner */}
           {showShareBanner && (
               <div className="bg-gradient-to-r from-indigo-50 to-blue-50 border border-blue-100 p-3 rounded-xl flex justify-between items-center relative mb-4">
                   <div className="text-left">
                       <p className="text-xs font-bold text-blue-800">Help your family ❤️</p>
                       <p className="text-[10px] text-blue-600">Share this app to keep them safe.</p>
                   </div>
                   <button 
                       onClick={shareApp} 
                       className="bg-blue-600 text-white px-3 py-1.5 rounded-lg text-xs font-bold shadow-sm"
                   >
                       Share
                   </button>
                   <button onClick={() => setShowShareBanner(false)} className="absolute -top-1 -right-1 bg-gray-200 rounded-full w-4 h-4 flex items-center justify-center text-[10px] text-gray-600">&times;</button>
               </div>
           )}

           <div className="relative group cursor-pointer w-full" onClick={triggerCamera}>
              <div className="absolute -inset-1 bg-gradient-to-r from-teal-400 to-blue-500 rounded-2xl blur opacity-25 group-hover:opacity-75 transition duration-1000 group-hover:duration-200"></div>
              <button className="relative w-full py-8 bg-white rounded-2xl flex flex-col items-center justify-center shadow-lg border border-teal-50 hover:scale-[1.02] transition-transform">
