import React, { useState, useEffect } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import PremiumModal from './components/PremiumModal';
import AlarmRingingModal from './components/AlarmRingingModal';
import LegalAndHelp from './components/LegalAndHelp';
import { MedicineData, AppView, Reminder, PatientProfile } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);

  const [isPremium, setIsPremium] = useState(false);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");

  // Alarm State
  const [ringingReminder, setRingingReminder] = useState<Reminder | null>(null);
  const [missedAlarm, setMissedAlarm] = useState<string | null>(null);

  // Load state
  useEffect(() => {
    const savedPremium = localStorage.getItem('mediScan_premium');
    if (savedPremium === 'true') setIsPremium(true);

    const savedReminders = localStorage.getItem('mediScan_reminders');
    if (savedReminders) setReminders(JSON.parse(savedReminders));

    // Check alarms frequently (every 10 seconds for better precision on web)
    const interval = setInterval(checkAlarms, 10000);

    getHealthTip().then(setHealthTip);

    return () => clearInterval(interval);
  }, []);

  // Save reminders
  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  // Remove missed alarm toast after 5s
  useEffect(() => {
      if (missedAlarm) {
          const timer = setTimeout(() => setMissedAlarm(null), 5000);
          return () => clearTimeout(timer);
      }
  }, [missedAlarm]);

  const checkAlarms = () => {
    // If already ringing, don't check
    if (ringingReminder) return;

    const now = new Date();
    const currentHours = String(now.getHours()).padStart(2, '0');
    const currentMinutes = String(now.getMinutes()).padStart(2, '0');
    const currentTime = `${currentHours}:${currentMinutes}`;
    const currentDay = now.getDay(); // 0 = Sun

    reminders.forEach(rem => {
        if (!rem.active) return;

        // Check Snooze
        if (rem.snoozedUntil) {
            if (Date.now() >= rem.snoozedUntil) {
                // Snooze over, trigger again
                triggerAlarm(rem);
            }
            return;
        }

        if (rem.time === currentTime) {
            // Check Repeat Logic
            let shouldRing = false;

            if (rem.repeat === 'daily') {
                shouldRing = true;
            } else if (rem.repeat === 'custom') {
                if (rem.customDays.includes(currentDay)) shouldRing = true;
            } else if (rem.repeat === 'alternate') {
                // Simple logic: Trigger every even day since creation.
                // In production, improved logic based on lastTaken is better.
                const oneDay = 24 * 60 * 60 * 1000;
                const daysSinceCreation = Math.floor((Date.now() - rem.createdAt) / oneDay);
                if (daysSinceCreation % 2 === 0) shouldRing = true;
            }

            if (shouldRing) {
                triggerAlarm(rem);
            }
        }
    });
  };

  const triggerAlarm = (rem: Reminder) => {
      // Avoid re-triggering same minute multiple times in one session if already ringing
      // (State check at start of checkAlarms handles basic concurrency)
      setRingingReminder(rem);

      // Clear snooze if it was snoozed
      if (rem.snoozedUntil) {
          updateReminder(rem.id, { snoozedUntil: null });
      }
  };

  const updateReminder = (id: string, updates: Partial<Reminder>) => {
      setReminders(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const handleTakeMedicine = () => {
      if (!ringingReminder) return;
      // Mark as taken (could log to history here)
      setRingingReminder(null);
  };

  const handleSnooze = (minutes: number) => {
      if (!ringingReminder) return;
      const snoozeTime = Date.now() + (minutes * 60 * 1000);
      updateReminder(ringingReminder.id, { snoozedUntil: snoozeTime });
      setRingingReminder(null);
  };

  const handleSkip = () => {
      if (!ringingReminder) return;
      setMissedAlarm(`You missed your dose of ${ringingReminder.medicineName}`);
      setRingingReminder(null);
  };

  const handleUpgrade = () => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    setShowPremiumModal(false);
  };

  const addReminder = (r: Reminder) => setReminders([...reminders, r]);
  const deleteReminder = (id: string) => setReminders(reminders.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(reminders.map(r => r.id === id ? { ...r, active: !r.active } : r));
  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    setScannedData(data);
    setPatientProfile(profile);
  };

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          profile={patientProfile}
          isPremium={isPremium} 
          onOpenPremium={() => setShowPremiumModal(true)}
          onClose={() => setScannedData(null)}
        />
      );
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="p-6">
            <header className="mb-8 flex justify-between items-start">
               <div>
                   <h1 className="text-3xl font-bold text-gray-900">MediScan <span className="text-teal-600">AI</span></h1>
                   <p className="text-gray-500 text-sm mt-1">Your pocket pharmacist</p>
               </div>
               <button onClick={() => setCurrentView(AppView.INFO)} className="text-gray-400 p-2 hover:bg-gray-100 rounded-full">
                   <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
               </button>
            </header>

            {healthTip && (
                 <div className="mb-6 p-3 bg-teal-50 border border-teal-100 rounded-lg text-xs text-teal-800 flex items-start animate-fade-in-down">
                    <span className="mr-2 text-lg">💡</span>
                    <span>{healthTip}</span>
                 </div>
            )}

            <Scanner 
              onScanComplete={handleScanComplete} 
              onError={(msg) => alert(msg)} 
            />

            {!isPremium && (
                <div 
                    onClick={() => setShowPremiumModal(true)}
                    className="mt-8 bg-gradient-to-r from-gray-900 to-gray-800 text-white p-5 rounded-2xl shadow-xl flex justify-between items-center cursor-pointer transform transition hover:scale-[1.02]"
                >
                    <div>
                        <h3 className="font-bold text-lg">Go Premium</h3>
                        <p className="text-xs text-gray-400">Unlock Side Effects & More</p>
                    </div>
                    <div className="bg-yellow-400 text-black px-3 py-1 rounded-lg font-bold text-sm">₹49</div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return (
          <Reminders 
            reminders={reminders} 
            addReminder={addReminder} 
            deleteReminder={deleteReminder}
            toggleReminder={toggleReminder}
          />
        );
      case AppView.INFO:
          return <LegalAndHelp />;
      default:
        return <div>View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto bg-gray-50 min-h-screen relative shadow-2xl overflow-hidden">

      {/* Missed Alarm Toast */}
      {missedAlarm && (
          <div className="absolute top-4 left-4 right-4 bg-red-500 text-white p-3 rounded-lg shadow-lg z-[110] animate-bounce flex items-center">
              <span className="text-2xl mr-3">⚠️</span>
              <div>
                  <h4 className="font-bold text-sm">Dose Missed</h4>
                  <p className="text-xs">{missedAlarm}</p>
              </div>
          </div>
      )}

      {/* Alarm Ringing Overlay */}
      {ringingReminder && (
          <AlarmRingingModal 
            reminder={ringingReminder}
            onTake={handleTakeMedicine}
            onSnooze={handleSnooze}
            onSkip={handleSkip}
          />
      )}

      {/* Main Content Area */}
      <main className="min-h-screen">
        {renderContent()}
      </main>

      {/* Navigation Bar (Bottom) */}
      {!scannedData && (
        <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-200 shadow-lg px-6 py-3 flex justify-around items-center z-40">
            <button 
                onClick={() => setCurrentView(AppView.HOME)}
                className={`flex flex-col items-center space-y-1 ${currentView === AppView.HOME || currentView === AppView.SCANNER ? 'text-teal-600' : 'text-gray-400'}`}
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
                <span className="text-xs font-medium">Scan</span>
            </button>

            <button 
                onClick={() => setCurrentView(AppView.REMINDERS)}
                className={`flex flex-col items-center space-y-1 ${currentView === AppView.REMINDERS ? 'text-teal-600' : 'text-gray-400'}`}
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <span className="text-xs font-medium">Alarms</span>
            </button>

            <button 
                onClick={() => setShowPremiumModal(true)}
                className={`flex flex-col items-center space-y-1 ${isPremium ? 'text-yellow-500' : 'text-gray-400'}`}
            >
                 <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span className="text-xs font-medium">{isPremium ? 'Premium' : 'Upgrade'}</span>
            </button>
        </nav>
      )}

      {/* Modals */}
      <PremiumModal 
        isOpen={showPremiumModal} 
        onClose={() => setShowPremiumModal(false)} 
        onUpgrade={handleUpgrade}
      />
    </div>
  );
};

