import { GoogleAuthProvider, signInWithPopup, signOut, User } from "firebase/auth";
import { doc, getDoc, setDoc } from "firebase/firestore";
import { auth, db } from "../firebaseConfig";

const googleProvider = new GoogleAuthProvider();

export const loginWithGoogle = async (): Promise<User | null> => {
  try {
    const result = await signInWithPopup(auth, googleProvider);
    return result.user;
  } catch (error) {
    console.error("Login failed", error);
    throw error;
  }
};

export const logoutUser = async () => {
  try {
    await signOut(auth);
  } catch (error) {
    console.error("Logout failed", error);
  }
};

export const syncPremiumStatus = async (user: User, isPremiumLocal: boolean): Promise<boolean> => {
  if (!user) return isPremiumLocal;

  try {
    const userRef = doc(db, "users", user.uid);
    const userSnap = await getDoc(userRef);

    if (userSnap.exists()) {
      const data = userSnap.data();
      // If Firestore says premium is true, return true (Restore)
      if (data.isPremium) {
        return true;
      }
    }

    // If local is premium but remote isn't (or doc doesn't exist), update remote
    if (isPremiumLocal) {
      await setDoc(userRef, { isPremium: true, email: user.email }, { merge: true });
    }

    return isPremiumLocal;
  } catch (error) {
    console.error("Error syncing premium:", error);
    return isPremiumLocal;
  }
};

export const setRemotePremium = async (uid: string) => {
    try {
        const userRef = doc(db, "users", uid);
        await setDoc(userRef, { isPremium: true }, { merge: true });
    } catch (e) {
        console.error("Failed to set remote premium", e);
    }
}

