  const verifyPayment = () => {
    if (txnId.length < 6) { setError("Invalid ID"); return; }
    setIsVerifying(true);
    setTimeout(() => {
      setIsVerifying(false); 
      onUpgrade(txnId); 
      setStep('INFO'); 
      setTxnId('');
    }, 2000);
  };

  const handleRestore = () => {
      if (restoreId.length < 3) { setError("Invalid ID"); return; }
      setIsVerifying(true);
