import { GoogleGenAI, Type, Schema } from "@google/genai";
import { MedicineData, PatientProfile } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MEDICINE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING, description: "Medicine name or 'Prescription for [Condition]'." },
    description: { type: Type.STRING, description: "Medical description." },
    simpleExplanation: { type: Type.STRING, description: "Simple explanation in requested language." },
    uses: { type: Type.ARRAY, items: { type: Type.STRING } },
    dosage: { type: Type.STRING },
    sideEffects: { type: Type.ARRAY, items: { type: Type.STRING } },
    warnings: { type: Type.STRING },
    riskScore: { type: Type.STRING, enum: ["Low", "Medium", "High"], description: "Overall risk level based on side effects/warnings." },
    riskReason: { type: Type.STRING, description: "Short reason for the risk score (e.g. 'High potential for drowsiness')." },
    whoShouldAvoid: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of people/conditions who should avoid this (e.g. 'Kidney patients', 'Drivers')." },
    foodGuidance: { type: Type.STRING, description: "Specific food instruction: 'Before Food', 'After Food', 'With Food', or 'Empty Stomach'." },
    alternatives: { type: Type.ARRAY, items: { type: Type.STRING }, description: "1-2 common safer alternatives (generic names). Informational only." },
    criticalWarning: { type: Type.STRING, description: "Populate ONLY if there is an immediate life-threatening risk or severe interaction. Otherwise null." },
    pregnancyWarning: { type: Type.STRING },
    breastfeedingWarning: { type: Type.STRING },
    ageAdvice: { type: Type.STRING }
  },
  required: ["name", "description", "simpleExplanation", "uses", "dosage", "sideEffects", "warnings", "riskScore", "riskReason", "whoShouldAvoid", "foodGuidance", "alternatives", "ageAdvice"]
};

export const analyzeMedicineImage = async (base64Image: string, profile: PatientProfile): Promise<MedicineData> => {
  try {
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");

    const profileDescription = `
      Patient Profile:
      - Age Group: ${profile.ageGroup}
      - Gender: ${profile.gender}
      - Pregnant: ${profile.isPregnant ? 'YES' : 'NO'}
      - Breastfeeding: ${profile.isBreastfeeding ? 'YES' : 'NO'}
      - Output Language: ${profile.language}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } },
          {
            text: `Analyze this medicine/prescription.
            ${profileDescription}

            REQUIREMENTS:
            1. Risk Score: Calculate based on side effects severity and profile suitability.
            2. Food Guidance: Be explicit (Before/After/With).
            3. Alternatives: Suggest 1-2 generic alternatives if applicable (labeled as 'Ask Doctor').
            4. Critical Warning: If this medicine is strictly prohibited for the current profile (e.g. Pregnant), set this field.

            Provide accurate medical info with disclaimers.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: MEDICINE_SCHEMA,
        systemInstruction: "You are an expert AI doctor assistant. Be concise, accurate, and safety-focused."
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as MedicineData;
    } else {
      throw new Error("No data returned from AI");
    }
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const checkConditionSafety = async (medicineName: string, condition: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Can a patient with "${condition}" take the medicine "${medicineName}"? 
      Reply in 1-2 short sentences. Start with "Safe", "Caution", or "Not Recommended".`
    });
    return response.text || "Consult your doctor.";
  } catch (e) {
    return "Unable to verify. Please consult a doctor.";
  }
};

export const getHealthTip = async (): Promise<string> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: "Give me one short, random, interesting daily health tip in 15 words or less."
        });
        return response.text || "Drink water and stay hydrated!";
    } catch (e) {
        return "Stay active and eat healthy!";
    }
}

import React, { useState, useEffect } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import PremiumModal from './components/PremiumModal';
import AlarmRingingModal from './components/AlarmRingingModal';
import LegalAndHelp from './components/LegalAndHelp';
import Profile from './components/Profile';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);

  // Premium State
  const [isPremium, setIsPremium] = useState<boolean>(() => {
    return localStorage.getItem('mediScan_premium') === 'true';
  });

  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);

  // Alarm State
  const [ringingReminder, setRingingReminder] = useState<Reminder | null>(null);
  const [missedAlarm, setMissedAlarm] = useState<string | null>(null);

  // Load state
  useEffect(() => {
    if (!localStorage.getItem('mediScan_deviceId')) {
        localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
    }

    const savedReminders = localStorage.getItem('mediScan_reminders');
    if (savedReminders) setReminders(JSON.parse(savedReminders));

    const savedHistory = localStorage.getItem('mediScan_history');
    if (savedHistory) setScanHistory(JSON.parse(savedHistory));

    const interval = setInterval(checkAlarms, 10000);
    getHealthTip().then(setHealthTip);
    return () => {
        clearInterval(interval);
    }
  }, []);

  // Save reminders
  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  // Save History
  useEffect(() => {
    localStorage.setItem('mediScan_history', JSON.stringify(scanHistory));
  }, [scanHistory]);

  useEffect(() => {
      if (missedAlarm) {
          const timer = setTimeout(() => setMissedAlarm(null), 5000);
          return () => clearTimeout(timer);
      }
  }, [missedAlarm]);

  const checkAlarms = () => {
    if (ringingReminder) return;

    const now = new Date();
    const currentHours = String(now.getHours()).padStart(2, '0');
    const currentMinutes = String(now.getMinutes()).padStart(2, '0');
    const currentTime = `${currentHours}:${currentMinutes}`;
    const currentDay = now.getDay();

    reminders.forEach(rem => {
        if (!rem.active) return;
        if (rem.snoozedUntil) {
            if (Date.now() >= rem.snoozedUntil) triggerAlarm(rem);
            return;
        }
        if (rem.time === currentTime) {
            let shouldRing = false;
            if (rem.repeat === 'daily') shouldRing = true;
            else if (rem.repeat === 'custom' && rem.customDays.includes(currentDay)) shouldRing = true;
            else if (rem.repeat === 'alternate') {
                const oneDay = 24 * 60 * 60 * 1000;
                const daysSinceCreation = Math.floor((Date.now() - rem.createdAt) / oneDay);
                if (daysSinceCreation % 2 === 0) shouldRing = true;
            }
            if (shouldRing) triggerAlarm(rem);
        }
    });
  };

  const triggerAlarm = (rem: Reminder) => {
      setRingingReminder(rem);
      if (rem.snoozedUntil) updateReminder(rem.id, { snoozedUntil: null });
  };

  const updateReminder = (id: string, updates: Partial<Reminder>) => {
      setReminders(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const handleTakeMedicine = () => setRingingReminder(null);
  const handleSnooze = (minutes: number) => {
      if (!ringingReminder) return;
      const snoozeTime = Date.now() + (minutes * 60 * 1000);
      updateReminder(ringingReminder.id, { snoozedUntil: snoozeTime });
      setRingingReminder(null);
  };
  const handleSkip = () => {
      if (!ringingReminder) return;
      setMissedAlarm(`Skipped: ${ringingReminder.medicineName}`);
      setRingingReminder(null);
  };

  const handleUpgrade = (txnId?: string) => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    if (txnId) {
        localStorage.setItem('mediScan_txnId', txnId);
    }
    setShowPremiumModal(false);
  };

  const addReminder = (r: Reminder) => setReminders([...reminders, r]);
  const deleteReminder = (id: string) => setReminders(reminders.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(reminders.map(r => r.id === id ? { ...r, active: !r.active } : r));

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    // Check Memory
    const prev = scanHistory.find(item => item.medicineName.toLowerCase() === data.name.toLowerCase());
    setIsPreviouslyScanned(!!prev);

    // Save to History (limit to 20)
    const newItem: ScanHistoryItem = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        medicineName: data.name,
        data: data
    };
    setScanHistory(prevHist => [newItem, ...prevHist].slice(0, 20));

    setScannedData(data);
    setPatientProfile(profile);
  };

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          profile={patientProfile}
          isPremium={isPremium} 
          isPreviouslyScanned={isPreviouslyScanned}
          onOpenPremium={() => setShowPremiumModal(true)}
          onClose={() => setScannedData(null)}
        />
      );
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="p-6 pb-32">
            <header className="mb-6 flex justify-between items-center animate-fade-in-down">
               <div>
                   <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">MedScan</h1>
                   <p className="text-gray-500 text-sm font-medium">Your AI Pharmacist</p>
               </div>
               <div className="flex space-x-2">
                   <button onClick={() => setCurrentView(AppView.INFO)} className="bg-white p-2.5 rounded-full shadow-sm border border-gray-100 text-gray-500 hover:text-teal-600 transition-colors">
                       <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                   </button>
                   <button onClick={() => setCurrentView(AppView.PROFILE)} className="bg-white p-1 rounded-full shadow-sm border border-gray-100 text-gray-500 hover:border-teal-500 transition-all">
                       <div className="w-9 h-9 rounded-full bg-gray-100 flex items-center justify-center relative">
                           {isPremium && <span className="absolute -top-1 -right-1 text-xs">👑</span>}
                           <svg className="w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                       </div>
                   </button>
               </div>
            </header>

            {healthTip && (
                 <div className="mb-6 p-4 bg-gradient-to-br from-teal-50 to-emerald-50 border border-teal-100 rounded-2xl flex items-start shadow-sm animate-fade-in-down" style={{animationDelay: '0.1s'}}>
                    <span className="mr-3 text-2xl">💡</span>
                    <span className="text-sm text-teal-900 font-medium leading-relaxed">{healthTip}</span>
                 </div>
            )}

            <Scanner 
              onScanComplete={handleScanComplete} 
              onError={(msg) => alert(msg)} 
            />

            {isPremium ? (
                 <div className="mt-8 bg-gradient-to-r from-blue-50 to-indigo-50 p-5 rounded-3xl border border-blue-100 shadow-sm animate-fade-in-up">
                    <h3 className="font-bold text-indigo-900 mb-3 flex items-center">
                        <svg className="w-5 h-5 mr-2 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                        Health Insights
                    </h3>
                    <div className="grid grid-cols-2 gap-3">
                        <div className="bg-white p-3 rounded-2xl text-center shadow-sm">
                            <span className="block text-2xl font-bold text-gray-800">{scanHistory.length}</span>
                            <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wide">Scans</span>
                        </div>
                        <div className="bg-white p-3 rounded-2xl text-center shadow-sm">
                            <span className="block text-2xl font-bold text-gray-800">{reminders.length}</span>
                            <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wide">Alarms</span>
                        </div>
                    </div>
                 </div>
            ) : (
                <div 
                    onClick={() => setShowPremiumModal(true)}
                    className="mt-8 bg-gray-900 text-white p-6 rounded-3xl shadow-xl flex justify-between items-center cursor-pointer transform transition-all hover:scale-[1.02] active:scale-95 group relative overflow-hidden"
                >
                    <div className="absolute inset-0 bg-gradient-to-r from-gray-800 to-gray-900 z-0"></div>
                    <div className="absolute top-0 right-0 -mt-4 -mr-4 w-24 h-24 bg-white opacity-5 rounded-full blur-xl"></div>

                    <div className="relative z-10">
                        <h3 className="font-bold text-lg group-hover:text-yellow-300 transition-colors">Go Premium 👑</h3>
                        <p className="text-xs text-gray-400 mt-1">Unlock Reports, Risks & Voices</p>
                    </div>
                    <div className="relative z-10 bg-gradient-to-r from-yellow-400 to-orange-500 text-white px-4 py-2 rounded-xl font-bold text-sm shadow-lg">
                        ₹99
                    </div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return (
          <Reminders 
            reminders={reminders} 
            addReminder={addReminder} 
            deleteReminder={deleteReminder}
            toggleReminder={toggleReminder}
          />
        );
      case AppView.INFO:
          return <LegalAndHelp />;
      case AppView.PROFILE:
          return <Profile isPremium={isPremium} />;
      default:
        return <div>View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen relative shadow-2xl overflow-hidden">
      {/* Background decoration */}
      <div className="fixed top-0 left-0 w-full h-96 bg-gradient-to-b from-teal-50/50 to-transparent pointer-events-none z-0"></div>

      {/* Missed Alarm Toast */}
      {missedAlarm && (
          <div className="absolute top-6 left-4 right-4 bg-red-500 text-white p-4 rounded-2xl shadow-2xl z-[110] animate-bounce flex items-center">
              <span className="text-2xl mr-4">⚠️</span>
              <div>
                  <h4 className="font-bold text-base">Dose Missed</h4>
                  <p className="text-xs opacity-90">{missedAlarm}</p>
              </div>
          </div>
      )}

      {ringingReminder && (
          <AlarmRingingModal 
            reminder={ringingReminder}
            onTake={handleTakeMedicine}
            onSnooze={handleSnooze}
            onSkip={handleSkip}
          />
      )}

      <main className="min-h-screen relative z-10">
        {renderContent()}
      </main>

      {!scannedData && (
        <nav className="fixed bottom-6 left-6 right-6 max-w-[calc(28rem-3rem)] mx-auto glass rounded-2xl shadow-2xl shadow-teal-900/10 px-6 py-4 flex justify-around items-center z-40 transform transition-transform">
            <button 
                onClick={() => setCurrentView(AppView.HOME)}
                className={`flex flex-col items-center space-y-1 transition-all duration-300 ${currentView === AppView.HOME || currentView === AppView.SCANNER ? 'text-teal-600 scale-110' : 'text-gray-400 hover:text-gray-600'}`}
            >
                {currentView === AppView.HOME || currentView === AppView.SCANNER ? (
                    <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                ) : (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                )}
                <span className="text-[10px] font-bold tracking-wide">Scan</span>
            </button>

            <button 
                onClick={() => setCurrentView(AppView.REMINDERS)}
                className={`flex flex-col items-center space-y-1 transition-all duration-300 ${currentView === AppView.REMINDERS ? 'text-teal-600 scale-110' : 'text-gray-400 hover:text-gray-600'}`}
            >
                {currentView === AppView.REMINDERS ? (
                    <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25-3 8.2-3 9v1h18v-1c0-.8-3-3.75-3-9 0-3.87-3.13-7-7-7z" /></svg>
                ) : (
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
                )}
                <span className="text-[10px] font-bold tracking-wide">Alarms</span>
            </button>

            <button 
                onClick={() => isPremium ? setCurrentView(AppView.PROFILE) : setShowPremiumModal(true)}
                className={`flex flex-col items-center space-y-1 transition-all duration-300 ${isPremium ? 'text-yellow-500 scale-110' : 'text-gray-400 hover:text-gray-600'}`}
            >
                {isPremium ? (
                     <svg className="w-7 h-7 drop-shadow-sm" fill="currentColor" viewBox="0 0 24 24"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
                ) : (
                     <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
                )}
                <span className="text-[10px] font-bold tracking-wide">{isPremium ? 'Premium' : 'Upgrade'}</span>
            </button>
        </nav>
      )}

      <PremiumModal 
        isOpen={showPremiumModal} 
        onClose={() => setShowPremiumModal(false)} 
        onUpgrade={handleUpgrade}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile } from '../types';
import { checkConditionSafety } from '../services/geminiService';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  isPreviouslyScanned: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ data, profile, isPremium, isPreviouslyScanned, onOpenPremium, onClose }) => {
  const [speaking, setSpeaking] = useState(false);
  const [feedbackGiven, setFeedbackGiven] = useState<'yes' | 'no' | null>(null);
  const [showCriticalModal, setShowCriticalModal] = useState(false);

  // Decision Support
  const [selectedCondition, setSelectedCondition] = useState('');
  const [conditionSafety, setConditionSafety] = useState('');
  const [checkingCondition, setCheckingCondition] = useState(false);

  useEffect(() => {
    // Show critical alert if risk is high or explicit warning exists
    if (data.riskScore === 'High' || data.criticalWarning) {
        setShowCriticalModal(true);
    }
    return () => { window.speechSynthesis.cancel(); }
  }, [data]);

  const toggleSpeech = () => {
    if (speaking) {
        window.speechSynthesis.cancel();
        setSpeaking(false);
    } else {
        const textToRead = `${data.name}. Risk Level: ${data.riskScore}. ${data.simpleExplanation}. ${data.ageAdvice}.`;
        const utterance = new SpeechSynthesisUtterance(textToRead);
        utterance.lang = profile?.language === 'hindi' ? 'hi-IN' : 'en-US';
        utterance.onend = () => setSpeaking(false);
        window.speechSynthesis.speak(utterance);
        setSpeaking(true);
    }
  };

  const handleShare = async () => {
      const shareData = {
          title: `MedScan Info: ${data.name}`,
          text: `Medicine: ${data.name}. Risk: ${data.riskScore}. ${data.simpleExplanation}.`,
          url: window.location.href
      };
      try {
          if (navigator.share) await navigator.share(shareData);
      } catch (err) {}
  };

  const handleCheckCondition = async () => {
      if (!selectedCondition) return;
      setCheckingCondition(true);
      const result = await checkConditionSafety(data.name, selectedCondition);
      setConditionSafety(result);
      setCheckingCondition(false);
  };

  const handleDownloadReport = () => {
      if (!isPremium) {
          onOpenPremium();
          return;
      }
      window.print();
  };

  return (
    <div className="pb-32 bg-gray-50 min-h-screen">

        {/* CRITICAL WARNING MODAL */}
        {showCriticalModal && (
            <div className="fixed inset-0 z-50 bg-red-900/95 flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-3xl p-6 shadow-2xl w-full max-w-sm text-center">
                     <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
                         <svg className="w-10 h-10 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                     </div>
                     <h2 className="text-2xl font-bold text-red-700 mb-2">High Risk Alert</h2>
                     <p className="text-gray-700 font-medium mb-4">
                         {data.criticalWarning || "This medicine has a High Risk profile for your condition."}
                     </p>
                     <div className="bg-red-50 p-3 rounded-xl mb-6 text-sm text-red-800 border border-red-200">
                         {data.riskReason}
                     </div>
                     <button onClick={() => setShowCriticalModal(false)} className="w-full bg-red-600 text-white py-3 rounded-xl font-bold hover:bg-red-700">
                         I Understand, Proceed
                     </button>
                </div>
            </div>
        )}

        {/* Hero Header */}
        <div className={`text-white rounded-b-[2.5rem] shadow-2xl relative overflow-hidden pb-12 transition-colors duration-500 ${data.riskScore === 'High' ? 'bg-red-700' : data.riskScore === 'Medium' ? 'bg-orange-600' : 'bg-teal-700'}`}>
            <div className="absolute top-0 right-0 -mr-10 -mt-10 w-64 h-64 bg-white opacity-5 rounded-full blur-3xl"></div>

            <div className="p-6 pt-8 relative z-10">
                <div className="flex justify-between items-start mb-6">
                    <div className="flex space-x-2">
                         <div className="bg-white/20 backdrop-blur-md px-3 py-1 rounded-full border border-white/20">
                            <span className="text-[10px] font-bold tracking-widest uppercase text-white">Risk: {data.riskScore}</span>
                        </div>
                        {isPreviouslyScanned && (
                             <div className="bg-blue-500/30 backdrop-blur-md px-3 py-1 rounded-full border border-blue-400/30 flex items-center">
                                <span className="text-[10px] font-bold text-white">Previously Scanned</span>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="bg-white/10 p-2 rounded-full hover:bg-white/20 transition-colors print:hidden">
                        <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <h2 className="text-3xl font-extrabold mb-2 leading-tight">{data.name}</h2>
                <p className="text-white/80 text-sm font-medium">{data.description}</p>

                {data.riskReason && (
                    <div className="mt-4 inline-block bg-black/20 px-3 py-1.5 rounded-lg text-xs text-white/90">
                        ⚠️ {data.riskReason}
                    </div>
                )}
            </div>

            {/* Floating Play Button */}
            <button 
                onClick={toggleSpeech}
                className="absolute -bottom-7 right-8 w-16 h-16 bg-yellow-400 rounded-full shadow-lg shadow-yellow-500/30 flex items-center justify-center text-black hover:scale-110 active:scale-95 transition-transform z-20 print:hidden"
            >
                {speaking ? (
                    <div className="flex space-x-1 items-center h-5">
                        <div className="w-1.5 h-6 bg-black animate-[bounce_1s_infinite_0ms]"></div>
                        <div className="w-1.5 h-6 bg-black animate-[bounce_1s_infinite_200ms]"></div>
                    </div>
                ) : (
                    <svg className="w-8 h-8 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                )}
            </button>
        </div>

        <div className="px-6 pt-10 space-y-6">

            {/* AI Doctor Summary */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden">
                <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500"></div>
                <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wider mb-2 flex items-center">
                    <svg className="w-5 h-5 mr-2 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    AI Doctor Summary
                </h3>
                <p className="text-gray-800 text-lg font-medium leading-relaxed">
                    "{data.simpleExplanation}"
                </p>
            </section>

             {/* Food Guidance */}
            <section className="bg-orange-50 p-5 rounded-2xl border border-orange-100 flex items-center">
                 <div className="w-12 h-12 bg-orange-100 text-orange-600 rounded-xl flex items-center justify-center mr-4 shadow-sm">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                 </div>
                 <div>
                     <h3 className="text-xs font-bold text-orange-800 uppercase">Food Intake</h3>
                     <p className="text-lg font-bold text-gray-900">{data.foodGuidance}</p>
                 </div>
            </section>

            {/* Who Should Avoid */}
            {data.whoShouldAvoid.length > 0 && (
                <div className="bg-red-50 p-5 rounded-2xl border border-red-100">
                    <h3 className="text-sm font-bold text-red-800 uppercase mb-3">Who Should Avoid This?</h3>
                    <ul className="space-y-2">
                        {data.whoShouldAvoid.map((item, i) => (
                            <li key={i} className="flex items-center text-sm text-gray-700 font-medium">
                                <span className="w-2 h-2 bg-red-400 rounded-full mr-3"></span>
                                {item}
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            {/* Decision Support */}
            <section className="bg-blue-50 p-5 rounded-2xl border border-blue-100">
                <h3 className="text-sm font-bold text-blue-900 uppercase mb-3">Should I take this if I have...?</h3>
                <div className="flex flex-wrap gap-2 mb-3">
                    {['Fever', 'High BP', 'Diabetes', 'Asthma', 'Pregnancy'].map(c => (
                        <button 
                            key={c} 
                            onClick={() => { setSelectedCondition(c); setConditionSafety(''); }}
                            className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${selectedCondition === c ? 'bg-blue-600 text-white shadow-md' : 'bg-white text-blue-700 border border-blue-200'}`}
                        >
                            {c}
                        </button>
                    ))}
                </div>
                {selectedCondition && (
                    <div className="bg-white p-3 rounded-xl border border-blue-100">
                         <div className="flex justify-between items-center mb-2">
                             <span className="text-xs font-bold text-gray-500">Check for: {selectedCondition}</span>
                             <button 
                                onClick={handleCheckCondition}
                                className="bg-blue-600 text-white px-3 py-1 rounded-lg text-xs font-bold hover:bg-blue-700"
                                disabled={checkingCondition}
                             >
                                 {checkingCondition ? 'Checking...' : 'Check Safety'}
                             </button>
                         </div>
                         {conditionSafety && (
                             <p className="text-sm font-bold text-gray-800 animate-fade-in">{conditionSafety}</p>
                         )}
                    </div>
                )}
            </section>

            {/* Alternatives */}
            <div className="bg-gray-100 p-5 rounded-2xl border border-gray-200">
                <div className="flex justify-between items-center mb-2">
                    <h3 className="text-sm font-bold text-gray-500 uppercase">Alternatives</h3>
                    <span className="text-[10px] bg-gray-200 px-2 py-0.5 rounded text-gray-500">Ask Doctor</span>
                </div>
                <div className="flex flex-wrap gap-2">
                    {data.alternatives.map((alt, i) => (
                        <span key={i} className="px-3 py-1 bg-white text-gray-700 rounded-lg text-sm font-medium border border-gray-200">
                            {alt}
                        </span>
                    ))}
                </div>
            </div>

            {/* Premium Reports */}
            <div className="mt-4 print:hidden">
                <button 
                    onClick={handleDownloadReport}
                    className={`w-full py-4 rounded-2xl font-bold shadow-lg flex items-center justify-center transition-all ${isPremium ? 'bg-gray-900 text-white hover:bg-gray-800' : 'bg-gradient-to-r from-yellow-400 to-orange-500 text-black'}`}
                >
                    <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    {isPremium ? 'Download Health Report' : 'Unlock PDF Report (Premium)'}
                </button>
            </div>

            <button 
                onClick={handleShare}
                className="w-full bg-teal-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-teal-600/30 hover:bg-teal-700 active:scale-95 transition-all flex items-center justify-center print:hidden"
            >
                Share with Family
            </button>

            {/* Feedback */}
            <div className="bg-white p-5 rounded-2xl shadow-sm print:hidden">
                {!feedbackGiven ? (
                    <div className="flex justify-around">
                        <button onClick={() => setFeedbackGiven('yes')} className="text-gray-500 hover:text-green-600 font-bold text-sm">👍 Helpful</button>
                        <button onClick={() => setFeedbackGiven('no')} className="text-gray-500 hover:text-red-600 font-bold text-sm">👎 Not Helpful</button>
                    </div>
                ) : (
                    <p className="text-center text-green-600 font-bold text-sm">Thank you for feedback!</p>
                )}
            </div>

            <div className="text-center py-4 border-t border-gray-200 print:block">
                 <p className="text-[10px] text-gray-400 font-medium">
                    MedScan AI does not provide medical diagnosis. Always consult a doctor.
                </p>
            </div>
        </div>

        {/* Print Styles for PDF Report */}
        <style>{`
            @media print {
                body * { visibility: hidden; }
                .pb-32 { padding-bottom: 0 !important; background: white !important; }
                .min-h-screen { min-height: auto !important; }
                .print\\:hidden { display: none !important; }
                .print\\:block { display: block !important; }

