import { GoogleGenAI, Type, Schema } from "@google/genai";
import { MedicineData, PatientProfile } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MEDICINE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    name: { type: Type.STRING, description: "Medicine name or 'Prescription for [Condition]'." },
    description: { type: Type.STRING, description: "Medical description." },
    simpleExplanation: { type: Type.STRING, description: "Simple explanation in requested language." },
    childFriendlyExplanation: { type: Type.STRING, description: "Explain like I am 10 years old. Very simple, no jargon. In requested language." },
    uses: { type: Type.ARRAY, items: { type: Type.STRING } },
    dosage: { type: Type.STRING },
    sideEffects: { type: Type.ARRAY, items: { type: Type.STRING } },
    warnings: { type: Type.STRING },
    keyWarning: { type: Type.STRING, description: "The single most important safety warning. Short and bold." },
    riskScore: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
    riskReason: { type: Type.STRING },
    whoShouldAvoid: { type: Type.ARRAY, items: { type: Type.STRING } },
    foodGuidance: { type: Type.STRING },
    alternatives: { type: Type.ARRAY, items: { type: Type.STRING } },
    effectTimeline: {
        type: Type.OBJECT,
        properties: {
            onset: { type: Type.STRING, description: "Time to start working (approx)." },
            peak: { type: Type.STRING, description: "Time to peak effect (approx)." },
            duration: { type: Type.STRING, description: "How long effect lasts (approx)." }
        },
        required: ["onset", "peak", "duration"]
    },
    lifestyleWarnings: {
        type: Type.OBJECT,
        properties: {
            alcohol: { type: Type.BOOLEAN, description: "True if alcohol should be avoided." },
            driving: { type: Type.BOOLEAN, description: "True if driving/heavy machinery should be avoided." },
            sleep: { type: Type.BOOLEAN, description: "True if it causes drowsiness." }
        },
        required: ["alcohol", "driving", "sleep"]
    },
    safetyRating: { type: Type.NUMBER, description: "Safety score 0-100 where 100 is safest (e.g. Paracetamol) and 0 is dangerous." },
    commonQuestions: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                question: { type: Type.STRING, description: "A common follow-up question (e.g. Is this addictive?)" },
                answer: { type: Type.STRING, description: "Short answer to the question." }
            },
            required: ["question", "answer"]
        },
        description: "Generate 3 common follow-up questions and answers."
    },
    criticalWarning: { type: Type.STRING },
    pregnancyWarning: { type: Type.STRING },
    breastfeedingWarning: { type: Type.STRING },
    ageAdvice: { type: Type.STRING }
  },
  required: [
    "name", "description", "simpleExplanation", "childFriendlyExplanation", "uses", "dosage", 
    "sideEffects", "warnings", "keyWarning", "riskScore", "riskReason", "whoShouldAvoid", 
    "foodGuidance", "alternatives", "ageAdvice", "effectTimeline", "lifestyleWarnings", "safetyRating", "commonQuestions"
  ]
};

export const analyzeMedicineImage = async (base64Image: string, profile: PatientProfile): Promise<MedicineData> => {
  try {
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");

    const profileDescription = `
      Patient Profile:
      - Age Group: ${profile.ageGroup}
      - Gender: ${profile.gender}
      - Pregnant: ${profile.isPregnant ? 'YES' : 'NO'}
      - Breastfeeding: ${profile.isBreastfeeding ? 'YES' : 'NO'}
      - Output Language: ${profile.language}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: cleanBase64 } },
          {
            text: `Analyze this medicine.
            ${profileDescription}

            Provide advanced safety intelligence including:
            1. 'childFriendlyExplanation': Use very simple language.
            2. 'effectTimeline': Approximate Onset, Peak, and Duration.
            3. 'lifestyleWarnings': Boolean flags for Alcohol, Driving, Drowsiness.
            4. 'safetyRating': A score from 0-100 (100 = Safe/Vitamin, 50 = Prescription Antibiotic, 20 = High Risk Painkiller).
            5. 'commonQuestions': 3 smart follow-up questions users might ask.

            Be accurate and cautious.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: MEDICINE_SCHEMA,
        systemInstruction: "You are MedScan AI, a highly intelligent and empathetic pharmacist. Analyze images carefully."
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as MedicineData;
    } else {
      throw new Error("No data returned from AI");
    }
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

export const checkConditionSafety = async (medicineName: string, condition: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Can a patient with "${condition}" take the medicine "${medicineName}"? 
      Reply in 1-2 short sentences. Start with "Safe", "Caution", or "Not Recommended".`
    });
    return response.text || "Consult your doctor.";
  } catch (e) {
    return "Unable to verify. Please consult a doctor.";
  }
};

export const getHealthTip = async (): Promise<string> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: "Give me one short, random, interesting daily health tip in 15 words or less."
        });
        return response.text || "Drink water and stay hydrated!";
    } catch (e) {
        return "Stay active and eat healthy!";
    }
}

