            {isPremium ? (
                 <div className="mt-8 bg-gradient-to-br from-indigo-50 to-white p-6 rounded-3xl border border-indigo-100 shadow-sm">
                    <h3 className="font-bold text-indigo-900 mb-4 flex items-center text-sm uppercase tracking-wide">
                        <svg className="w-5 h-5 mr-2 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                        Your Health Stats
                    </h3>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white p-4 rounded-2xl text-center shadow-sm border border-slate-50">
                            <span className="block text-3xl font-extrabold text-slate-800 mb-1">{scanHistory.length}</span>
                            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Scans</span>
                        </div>
                        <div className="bg-white p-4 rounded-2xl text-center shadow-sm border border-slate-50">
                            <span className="block text-3xl font-extrabold text-slate-800 mb-1">{reminders.length}</span>
                            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Alarms</span>
                        </div>
                    </div>
                 </div>
            ) : (
                <div 
                    onClick={() => setShowPremiumModal(true)}
                    className="mt-8 bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-900/10 flex justify-between items-center cursor-pointer transform transition-all hover:scale-[1.02] active:scale-95 group relative overflow-hidden"
                >
                    <div className="absolute inset-0 bg-gradient-to-r from-slate-800 to-slate-900 z-0"></div>
                    <div className="absolute -top-12 -right-12 w-40 h-40 bg-white opacity-5 rounded-full blur-2xl group-hover:opacity-10 transition-opacity"></div>

                    <div className="relative z-10">
                        <h3 className="font-bold text-lg group-hover:text-yellow-300 transition-colors flex items-center">
                            Go Premium <span className="ml-2 text-xl">👑</span>
                        </h3>
                        <p className="text-xs text-slate-400 mt-1 font-medium">Unlock Reports, Risks & Voices</p>
                    </div>
                    <div className="relative z-10 bg-gradient-to-r from-yellow-400 to-orange-500 text-slate-900 px-5 py-2.5 rounded-xl font-bold text-sm shadow-lg">
                        ₹99
                    </div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return (
          <Reminders 
            reminders={reminders} 
            addReminder={addReminder} 
            deleteReminder={deleteReminder}
            toggleReminder={toggleReminder}
          />
        );
      case AppView.INFO:
          return <LegalAndHelp />;
      case AppView.PROFILE:
          return <Profile isPremium={isPremium} />;
      default:
        return <div className="p-10 text-center">View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto bg-slate-50 min-h-screen relative shadow-2xl overflow-hidden font-sans text-slate-800">

      {/* Dynamic Background */}
      <div className="fixed top-0 left-0 w-full h-[50vh] bg-gradient-to-b from-teal-50/80 to-transparent pointer-events-none z-0"></div>

      {/* Toast Notification */}
      {missedAlarm && (
          <div className="absolute top-6 left-4 right-4 bg-red-500 text-white p-4 rounded-2xl shadow-xl shadow-red-500/20 z-[110] animate-slide-up flex items-center justify-between">
              <div className="flex items-center">
                  <span className="text-2xl mr-3">⚠️</span>
                  <div>
                      <h4 className="font-bold text-sm">Dose Missed</h4>
                      <p className="text-xs opacity-90">{missedAlarm}</p>
                  </div>
              </div>
              <button onClick={() => setMissedAlarm(null)} className="text-white/80 hover:text-white">✕</button>
          </div>
      )}

      {ringingReminder && (
          <AlarmRingingModal 
            reminder={ringingReminder}
            onTake={handleTakeMedicine}
            onSnooze={handleSnooze}
            onSkip={handleSkip}
          />
      )}

      <main className="min-h-screen relative z-10 overflow-y-auto hide-scrollbar">
        {renderContent()}
      </main>

      {!scannedData && (
        <nav className="fixed bottom-6 left-6 right-6 max-w-[calc(28rem-3rem)] mx-auto glass rounded-3xl shadow-2xl shadow-slate-400/20 px-2 py-3 flex justify-around items-center z-40">
            {[
                { view: AppView.HOME, icon: "M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z", label: "Scan" },
                { view: AppView.REMINDERS, icon: "M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9", label: "Alarms" },
                { view: AppView.PROFILE, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: isPremium ? "Profile" : "Premium" }
            ].map((item) => {
                const isActive = currentView === item.view || (item.view === AppView.HOME && currentView === AppView.SCANNER);
                // Special handle for premium tab when not premium
                const handleClick = () => {
                    if (item.view === AppView.PROFILE && !isPremium) {
                        setShowPremiumModal(true);
                    } else {
                        setCurrentView(item.view);
                    }
                };

                return (
                    <button 
                        key={item.label}
                        onClick={handleClick}
                        className={`flex flex-col items-center justify-center w-20 h-16 rounded-2xl transition-all duration-300 ${isActive ? 'bg-teal-50 text-teal-600' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50/50'}`}
                    >
                        <svg className={`w-6 h-6 mb-1 ${isActive ? 'stroke-2' : 'stroke-[1.5]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" d={item.icon} />
                        </svg>
                        <span className={`text-[10px] font-bold tracking-wide ${isActive ? 'opacity-100' : 'opacity-80'}`}>{item.label}</span>
                    </button>
                );
            })}
        </nav>
      )}

      <PremiumModal 
        isOpen={showPremiumModal} 
        onClose={() => setShowPremiumModal(false)} 
        onUpgrade={handleUpgrade}
      />
    </div>
  );
};

