import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData, PatientProfile, AgeGroup, Gender, Language } from '../types';

interface ScannerProps {
  onScanComplete: (data: MedicineData, profile: PatientProfile) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScanComplete, onError }) => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [showShareBanner, setShowShareBanner] = useState(true);
  const [qualityWarning, setQualityWarning] = useState<string | null>(null);

  // Profile State
  const [ageGroup, setAgeGroup] = useState<AgeGroup>('adult');
  const [gender, setGender] = useState<Gender>('male');
  const [isPregnant, setIsPregnant] = useState(false);
  const [isBreastfeeding, setIsBreastfeeding] = useState(false);
  const [language, setLanguage] = useState<Language>('english');

  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  // AI Camera Quality Intelligence
  const checkImageQuality = (file: File): Promise<string | null> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = URL.createObjectURL(file);
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(null); return; }

            ctx.drawImage(img, 0, 0);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const data = imageData.data;
            let r, g, b, avg;
            let colorSum = 0;

            for(let x = 0, len = data.length; x < len; x+=4) {
                r = data[x];
                g = data[x+1];
                b = data[x+2];
                avg = Math.floor((r+g+b)/3);
                colorSum += avg;
            }

            const brightness = Math.floor(colorSum / (img.width * img.height));

            if (brightness < 50) resolve("Too dark. Use flash 📸");
            else if (brightness > 230) resolve("Too bright. Reduce glare ☀️");
            else resolve(null); // Good quality
        };
    });
  };

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Check Quality
    const warning = await checkImageQuality(file);
    setQualityWarning(warning);

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      setImagePreview(base64);
      setShowForm(true); 
    };
    reader.readAsDataURL(file);
  }, []);

  const startAnalysis = async () => {
    if (!imagePreview) return;
    setShowForm(false);
    setAnalyzing(true);

    const profile: PatientProfile = {
        ageGroup,
        gender,
        isPregnant: gender === 'female' ? isPregnant : false,
        isBreastfeeding: gender === 'female' ? isBreastfeeding : false,
        language
    };

    try {
      const data = await analyzeMedicineImage(imagePreview, profile);
      onScanComplete(data, profile);
    } catch (err) {
      onError("Scan failed. Please try again.");
      setImagePreview(null);
      setShowForm(false);
    } finally {
      setAnalyzing(false);
    }
  };

  const shareApp = async () => {
      try {
          if (navigator.share) {
              await navigator.share({
                  title: 'MedScan',
                  text: 'Check out MedScan - AI Pharmacist for your family! 🏥',
                  url: window.location.href
              });
          }
      } catch (e) {}
  };

  const triggerCamera = () => cameraInputRef.current?.click();
  const triggerGallery = () => galleryInputRef.current?.click();

  if (showForm && imagePreview) {
      return (
          <div className="w-full max-w-md mx-auto bg-white rounded-[2rem] shadow-2xl overflow-hidden animate-slide-up relative z-50">
              <div className="h-64 relative group">
                  <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-slate-900/30 to-transparent flex flex-col justify-end p-6">
                      <h3 className="text-white font-bold text-2xl mb-1">Who is this for?</h3>
                      <p className="text-slate-300 text-sm">Customize safety profile</p>
                  </div>

                  {qualityWarning && (
                      <div className="absolute top-4 left-4 right-4 bg-orange-500/90 backdrop-blur-md text-white px-4 py-3 rounded-2xl flex items-center shadow-lg border border-white/10 animate-pulse">
                          <span className="mr-3 text-xl">⚠️</span>
                          <span className="text-sm font-bold">{qualityWarning}</span>
                      </div>
                  )}
              </div>

              <div className="p-6 space-y-6 bg-white">
                  {/* Language Selection */}
                   <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Output Language</label>
                      <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                          {(['english', 'hindi', 'hinglish'] as Language[]).map(l => (
                              <button
                                  key={l}
                                  onClick={() => setLanguage(l)}
                                  className={`flex-1 py-2.5 rounded-xl text-xs font-bold capitalize transition-all duration-300 ${language === l ? 'bg-white text-teal-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                              >
                                  {l}
                              </button>
                          ))}
                      </div>
                  </div>

                  {/* Age Group */}
                  <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Age Group</label>
                      <div className="grid grid-cols-3 gap-3">
                          {[
                              { id: 'child', emoji: '👶', label: 'Child' },
                              { id: 'adult', emoji: '🧑', label: 'Adult' },
                              { id: 'senior', emoji: '👴', label: 'Senior' }
                          ].map((item) => (
                             <button 
                                key={item.id}
                                onClick={() => setAgeGroup(item.id as AgeGroup)} 
                                className={`py-4 rounded-2xl border transition-all duration-300 active:scale-95 ${ageGroup === item.id ? 'border-teal-500 bg-teal-50 text-teal-800 ring-2 ring-teal-500/20' : 'border-slate-100 bg-white text-slate-600 hover:bg-slate-50'}`}
                            >
                                <span className="block text-2xl mb-1">{item.emoji}</span>
                                <span className="text-xs font-bold">{item.label}</span>
                            </button>
                          ))}
                      </div>
                  </div>

                  {/* Gender */}
                  <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Gender</label>
                      <div className="grid grid-cols-2 gap-4">
                          <button onClick={() => { setGender('male'); setIsPregnant(false); setIsBreastfeeding(false); }} className={`py-3.5 rounded-2xl font-bold text-sm transition-all ${gender === 'male' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}>
                              Male
                          </button>
                          <button onClick={() => setGender('female')} className={`py-3.5 rounded-2xl font-bold text-sm transition-all ${gender === 'female' ? 'bg-rose-500 text-white shadow-lg shadow-rose-500/30' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}>
                              Female
                          </button>
                      </div>
                  </div>

                  {/* Pregnancy/Breastfeeding Checks (Only for Female) */}
                  {gender === 'female' && (
                      <div className="bg-rose-50 p-5 rounded-2xl space-y-4 border border-rose-100 animate-fade-in">
                          {[
                              { label: "Pregnant 🤰", state: isPregnant, setter: setIsPregnant },
                              { label: "Breastfeeding 🤱", state: isBreastfeeding, setter: setIsBreastfeeding }
                          ].map((item, i) => (
                              <label key={i} className="flex items-center space-x-3 cursor-pointer group select-none">
                                  <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-colors ${item.state ? 'bg-rose-500 border-rose-500' : 'bg-white border-rose-200'}`}>
                                      {item.state && <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                                  </div>
                                  <input type="checkbox" checked={item.state} onChange={(e) => item.setter(e.target.checked)} className="hidden" />
                                  <span className="text-slate-800 font-bold text-sm">{item.label}</span>
                              </label>
                          ))}
                      </div>
                  )}

                  <div className="pt-4 space-y-3">
                    <button 
                        onClick={startAnalysis}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-900/20 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center"
                    >
                        <span>Run AI Analysis</span>
                        <svg className="ml-2 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                    </button>
                    <button onClick={() => { setImagePreview(null); setShowForm(false); }} className="w-full text-center py-3 text-slate-400 font-bold text-xs hover:text-slate-600 transition-colors uppercase tracking-widest">
                        Discard & Retake
                    </button>
                  </div>
              </div>
          </div>
      )
  }

  return (
    <div className="flex flex-col items-center w-full">
      <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} onChange={handleFileChange} className="hidden" />
      <input type="file" accept="image/*" ref={galleryInputRef} onChange={handleFileChange} className="hidden" />

      {analyzing ? (
        <div className="text-center p-8 bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm mx-4 relative overflow-hidden mt-10 border border-slate-100">
            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-teal-400 via-blue-500 to-teal-400 animate-[shimmer_2s_infinite]"></div>

            <div className="relative w-28 h-28 mx-auto mb-8">
                {imagePreview && (
                    <img src={imagePreview} alt="Scanning" className="w-full h-full object-cover rounded-full border-[6px] border-white shadow-lg relative z-10" />
                )}
                <div className="absolute -inset-1 rounded-full border-[3px] border-teal-500 border-t-transparent animate-spin z-20"></div>
                <div className="absolute -inset-5 rounded-full border-2 border-teal-200 animate-pulse z-0"></div>
            </div>

            <h3 className="text-2xl font-extrabold text-slate-900 mb-2">Analyzing...</h3>
            <p className="text-slate-500 text-sm font-medium mb-6">Checking databases for <span className="text-teal-600 font-bold">{ageGroup}</span> safety</p>

            <div className="flex flex-col space-y-2 max-w-[180px] mx-auto opacity-50">
                <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                    <div className="h-full bg-teal-500 animate-[width_1.5s_ease-in-out_infinite] rounded-full" style={{width: '60%'}}></div>
                </div>
            </div>
        </div>
      ) : (
        <div className="w-full space-y-5 animate-slide-up">

           {/* Soft Share Banner */}
           {showShareBanner && (
               <div className="bg-gradient-to-r from-teal-50 to-white border border-teal-100 p-4 rounded-3xl flex justify-between items-center relative shadow-sm">
                   <div className="flex items-center">
                       <div className="w-10 h-10 bg-white text-teal-600 rounded-full flex items-center justify-center mr-3 shadow-sm border border-teal-50">
                           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                       </div>
                       <div>
                           <p className="text-sm font-bold text-slate-800">Family Care</p>
                           <p className="text-xs text-slate-500">Scan for your parents safely.</p>
                       </div>
                   </div>
                   <button 
                       onClick={shareApp} 
                       className="bg-white text-teal-700 px-4 py-2 rounded-xl text-xs font-bold shadow-md hover:bg-teal-50 transition-colors border border-teal-50"
                   >
                       Share
                   </button>
                   <button onClick={() => setShowShareBanner(false)} className="absolute -top-2 -right-2 bg-white shadow-md border border-slate-100 rounded-full w-6 h-6 flex items-center justify-center text-slate-400 hover:text-red-500 text-sm font-bold">&times;</button>
               </div>
           )}

           {/* Main Camera Button */}
           <button 
              onClick={triggerCamera}
              className="group relative w-full h-56 rounded-[2.5rem] overflow-hidden shadow-2xl shadow-teal-900/20 transition-all duration-300 hover:scale-[1.01] active:scale-95"
           >
              <div className="absolute inset-0 bg-gradient-to-br from-teal-500 to-emerald-600 transition-colors group-hover:from-teal-600 group-hover:to-emerald-700"></div>

              {/* Decorative Circles */}
              <div className="absolute -top-10 -right-10 w-40 h-40 bg-white opacity-10 rounded-full blur-2xl"></div>
              <div className="absolute bottom-0 left-0 w-32 h-32 bg-teal-900 opacity-10 rounded-full blur-2xl"></div>

              <div className="absolute inset-0 flex flex-col items-center justify-center text-white z-10">
                  <div className="w-20 h-20 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform duration-300 border border-white/30 animate-pulse-soft">
                       <svg className="w-9 h-9" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <h3 className="text-3xl font-extrabold tracking-tight">Tap to Scan</h3>
                  <p className="text-teal-100 font-medium mt-1 text-sm tracking-wide bg-teal-800/20 px-3 py-1 rounded-lg">Medicine Box • Prescription</p>
              </div>
           </button>

           {/* Upload Button */}
           <button 
             onClick={triggerGallery}
             className="w-full bg-white text-slate-800 py-5 px-6 rounded-[2rem] font-bold shadow-xl shadow-slate-200/50 border border-slate-50 flex items-center justify-between hover:bg-slate-50 transition-all active:scale-95 group"
