      ) : (
        <div className="w-full space-y-6 animate-slide-up">
           <button onClick={triggerCamera} className="group relative w-full h-64 rounded-[3.5rem] overflow-hidden shadow-2xl shadow-teal-900/30 transition-all duration-500 hover:scale-[1.02] active:scale-95">
              <div className="absolute inset-0 bg-gradient-to-br from-teal-500 to-emerald-600 transition-colors group-hover:from-teal-600 group-hover:to-emerald-700"></div>
              <div className="absolute -top-10 -right-10 w-48 h-48 bg-white/10 rounded-full blur-3xl group-hover:scale-125 transition-transform duration-700"></div>
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white z-10">
                  <div className="w-24 h-24 bg-white/20 backdrop-blur-xl rounded-[2.5rem] flex items-center justify-center mb-6 group-hover:rotate-[15deg] transition-all duration-500 border border-white/30 shadow-2xl animate-pulse-soft">
                       <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <h3 className="text-4xl font-black tracking-tighter mb-1">Tap to Scan</h3>
                  <p className="text-teal-100 font-black text-[10px] tracking-[0.3em] uppercase opacity-80">Box • Stripe • Prescription</p>
