        </div>
        <button onClick={() => setShowForm(!showForm)} className="bg-slate-900 text-white w-14 h-14 rounded-2xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-90 transition-all border-b-4 border-black">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-[3rem] shadow-2xl border border-slate-50 mb-10 space-y-8 animate-slide-up relative z-10">
            <h3 className="text-xl font-black text-slate-900 flex items-center"><span className="w-2 h-2 bg-teal-500 rounded-full mr-3"></span> New Reminder</h3>

            <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Medicine</label>
                    <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Name" required className="w-full p-4 bg-slate-50 rounded-2xl border-none font-bold text-slate-800 placeholder-slate-300 focus:ring-4 focus:ring-teal-500/10" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Dose</label>
                    <input type="text" value={dose} onChange={(e) => setDose(e.target.value)} placeholder="Dose" required className="w-full p-4 bg-slate-50 rounded-2xl border-none font-bold text-slate-800 placeholder-slate-300 focus:ring-4 focus:ring-teal-500/10" />
                </div>
            </div>

            <div className="grid grid-cols-2 gap-5">
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Time</label>
                    <input type="time" value={time} onChange={(e) => setTime(e.target.value)} required className="w-full p-4 bg-slate-50 rounded-2xl border-none font-black text-xl text-teal-700" />
                </div>
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Intake</label>
                    <select value={foodContext} onChange={(e) => setFoodContext(e.target.value as FoodContext)} className="w-full p-4 bg-slate-50 rounded-2xl border-none font-bold text-xs text-slate-700">
                        <option value="before_food">Before Food 🍎</option>
                        <option value="after_food">After Food 🥣</option>
                        <option value="empty_stomach">Empty Stomach 🚫</option>
