                    </select>
                </div>
            </div>

            <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Smart Sound System</label>
                <div className="grid grid-cols-4 gap-2">
                     {(['default', 'soft', 'loud', 'zen', 'emergency', 'musical', 'ringtone', 'voice'] as SoundType[]).map(s => (
