import React, { useEffect, useRef, useState } from 'react';
import { Reminder } from '../types';

interface AlarmRingingModalProps {
  reminder: Reminder;
  onTake: () => void;
  onSnooze: (minutes: number) => void;
  onSkip: () => void;
}

const AlarmRingingModal: React.FC<AlarmRingingModalProps> = ({ reminder, onTake, onSnooze, onSkip }) => {
  const [volumeLevel, setVolumeLevel] = useState(0.2);
  const audioContextRef = useRef<AudioContext | null>(null);
  const intervalRef = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.vibrate) {
        const pattern = reminder.soundType === 'loud' || reminder.soundType === 'emergency' ? [500, 200, 500, 200] : [200, 1000];
        navigator.vibrate(pattern);
        const vibeInterval = setInterval(() => navigator.vibrate(pattern), 2000);
        return () => { clearInterval(vibeInterval); navigator.vibrate(0); };
    }
  }, [reminder.soundType]);

  useEffect(() => {
    let stopAudio = () => {};
    if (reminder.soundType === 'voice') {
       const speak = () => {
           window.speechSynthesis.cancel();
           const tone = reminder.voiceTone || 'normal';
           let text = tone === 'strict' ? `Attention! Take ${reminder.medicineName} now.` : tone === 'friendly' ? `Medicine time for ${reminder.medicineName}!` : tone === 'hindi' ? `${reminder.medicineName} dawai ka samay ho gaya hai.` : `Time for ${reminder.medicineName}.`;
           const utterance = new SpeechSynthesisUtterance(text);
           if (tone === 'hindi') utterance.lang = 'hi-IN';
           window.speechSynthesis.speak(utterance);
       };
       speak();
       const voiceInterval = setInterval(speak, 7000);
       stopAudio = () => { clearInterval(voiceInterval); window.speechSynthesis.cancel(); };
    } else {
       try {
           const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
           audioContextRef.current = ctx;
           const playPattern = (vol: number) => {
               const playTone = (freq: number, start: number, duration: number, type: OscillatorType = 'sine') => {
                    const osc = ctx.createOscillator();
                    const g = ctx.createGain();
                    osc.type = type;
                    osc.frequency.setValueAtTime(freq, ctx.currentTime + start);
                    g.gain.setValueAtTime(0, ctx.currentTime + start);
                    g.gain.linearRampToValueAtTime(vol, ctx.currentTime + start + 0.05);
                    g.gain.linearRampToValueAtTime(0, ctx.currentTime + start + duration);
                    osc.connect(g); g.connect(ctx.destination);
                    osc.start(ctx.currentTime + start); osc.stop(ctx.currentTime + start + duration);
               };

               if (reminder.soundType === 'soft') playTone(300, 0, 0.5);
               else if (reminder.soundType === 'loud') { playTone(800, 0, 0.3, 'square'); playTone(800, 0.4, 0.3, 'square'); }
               else if (reminder.soundType === 'zen') { playTone(200, 0, 1, 'sine'); playTone(300, 0.5, 1, 'sine'); }
               else if (reminder.soundType === 'emergency') { for(let i=0; i<4; i++) playTone(1200 - (i*100), i*0.15, 0.1, 'sawtooth'); }
               else if (reminder.soundType === 'musical') { playTone(440, 0, 0.2, 'triangle'); playTone(554.37, 0.2, 0.2, 'triangle'); playTone(659.25, 0.4, 0.4, 'triangle'); }
               else if (reminder.soundType === 'ringtone') { for(let i=0; i<3; i++) { playTone(600, i*0.2, 0.1); playTone(800, i*0.2 + 0.1, 0.1); } }
               else playTone(440, 0, 0.3, 'square');
           };
           playPattern(volumeLevel);
           const toneInterval = window.setInterval(() => playPattern(volumeLevel), reminder.soundType === 'emergency' || reminder.soundType === 'ringtone' ? 1000 : 2500);
           intervalRef.current = toneInterval;
           stopAudio = () => { if (intervalRef.current) clearInterval(intervalRef.current); if (ctx.state !== 'closed') ctx.close(); };
       } catch (e) {}
    }
    return stopAudio;
  }, [reminder, volumeLevel]);

  useEffect(() => {
      const volInterval = setInterval(() => setVolumeLevel(p => Math.min(p + 0.1, 0.8)), 4000);
      return () => clearInterval(volInterval);
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 flex items-center justify-center p-6 backdrop-blur-xl animate-fade-in">
      <div className="bg-white w-full max-w-sm rounded-[3.5rem] shadow-2xl overflow-hidden text-center relative border border-white/20">
        <div className="bg-teal-500 p-10 flex justify-center relative">
            <div className="absolute inset-0 bg-gradient-to-br from-teal-400 to-emerald-600"></div>
            <div className="relative">
                <div className="absolute inset-0 bg-white rounded-full animate-ping opacity-20"></div>
                <div className="bg-white rounded-[2rem] p-6 relative z-10 text-teal-600 shadow-2xl animate-bounce">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
                </div>
            </div>
        </div>
        <div className="p-10 space-y-6">
            <div>
                <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-1 leading-none">{reminder.medicineName}</h2>
                <p className="text-teal-600 font-black text-xl tracking-tight uppercase">{reminder.dose}</p>
            </div>
            <div className="inline-block bg-slate-900 text-white px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest">
                {reminder.foodContext.replace('_', ' ')}
            </div>
            <div className="space-y-4 pt-4">
                <button onClick={onTake} className="w-full bg-teal-600 text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-teal-600/30 hover:scale-[1.02] active:scale-95 transition-all">💊 I Have Taken</button>
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => onSnooze(10)} className="bg-slate-100 text-slate-500 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200">Snooze 10m</button>
                    <button onClick={() => onSnooze(30)} className="bg-slate-100 text-slate-500 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200">Snooze 30m</button>
                </div>
                <button onClick={() => confirm("Skip dose? This is not recommended.") && onSkip()} className="text-rose-400 text-[10px] font-black uppercase tracking-widest underline opacity-60">Skip This Dose</button>
            </div>
        </div>
      </div>
    </div>
  );
};

