import React, { useState, useEffect, Suspense } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import PremiumModal from './components/PremiumModal';
import AlarmRingingModal from './components/AlarmRingingModal';
import LegalAndHelp from './components/LegalAndHelp';
import Profile from './components/Profile';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);

  const [isPremium, setIsPremium] = useState<boolean>(() => {
    try {
      return localStorage.getItem('mediScan_premium') === 'true';
    } catch {
      return false;
    }
  });

  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);

  const [ringingReminder, setRingingReminder] = useState<Reminder | null>(null);
  const [missedAlarm, setMissedAlarm] = useState<string | null>(null);

  useEffect(() => {
    try {
      if (!localStorage.getItem('mediScan_deviceId')) {
          localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
      }
      const savedReminders = localStorage.getItem('mediScan_reminders');
      if (savedReminders) setReminders(JSON.parse(savedReminders));
      const savedHistory = localStorage.getItem('mediScan_history');
      if (savedHistory) setScanHistory(JSON.parse(savedHistory));
      getHealthTip().then(setHealthTip).catch(() => setHealthTip("Stay hydrated and check expiry dates."));
    } catch (e) {
      console.error("Initialization error", e);
    }
  }, []);

  useEffect(() => {
    const interval = setInterval(checkAlarms, 10000);
    return () => clearInterval(interval);
  }, [reminders]);

  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  useEffect(() => {
    localStorage.setItem('mediScan_history', JSON.stringify(scanHistory));
  }, [scanHistory]);

  const checkAlarms = () => {
    if (ringingReminder) return;
    const now = new Date();
    const currentTime = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    const currentDay = now.getDay();

    reminders.forEach(rem => {
        if (!rem.active) return;
        if (rem.snoozedUntil) {
            if (Date.now() >= rem.snoozedUntil) triggerAlarm(rem);
            return;
        }
        if (rem.time === currentTime) {
            let shouldRing = false;
            if (rem.repeat === 'daily') shouldRing = true;
            else if (rem.repeat === 'custom' && rem.customDays.includes(currentDay)) shouldRing = true;
            else if (rem.repeat === 'alternate') {
                const oneDay = 24 * 60 * 60 * 1000;
                const daysSinceCreation = Math.floor((Date.now() - rem.createdAt) / oneDay);
                if (daysSinceCreation % 2 === 0) shouldRing = true;
            }
            if (shouldRing) triggerAlarm(rem);
        }
    });
  };

  const triggerAlarm = (rem: Reminder) => {
      setRingingReminder(rem);
      if (rem.snoozedUntil) updateReminder(rem.id, { snoozedUntil: null });
  };

  const updateReminder = (id: string, updates: Partial<Reminder>) => {
      setReminders(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const handleTakeMedicine = () => setRingingReminder(null);
  const handleSnooze = (minutes: number) => {
      if (!ringingReminder) return;
      const snoozeTime = Date.now() + (minutes * 60 * 1000);
      updateReminder(ringingReminder.id, { snoozedUntil: snoozeTime });
      setRingingReminder(null);
  };
  const handleSkip = () => {
      if (!ringingReminder) return;
      setMissedAlarm(`Skipped: ${ringingReminder.medicineName}`);
      setRingingReminder(null);
  };

  const handleUpgrade = (txnId?: string) => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    if (txnId) localStorage.setItem('mediScan_txnId', txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => {
        const isSameMed = item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim();
        const isRecent = (now - item.timestamp) < fourHours;
        return isSameMed && isRecent;
    });
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const renderContent = () => {
    if (scannedData) {
      return <MedicineResult data={scannedData} profile={patientProfile} isPremium={isPremium} isPreviouslyScanned={isPreviouslyScanned} overdoseWarning={overdoseWarning} onOpenPremium={() => setShowPremiumModal(true)} onClose={() => setScannedData(null)} />;
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="px-6 pt-10 pb-32 animate-fade-in max-w-lg mx-auto">
            <header className="mb-10 flex justify-between items-center">
               <div className="group cursor-default">
                   <div className="flex items-center space-x-2.5">
                       <h1 className="text-4xl font-extrabold tracking-tighter bg-gradient-to-br from-slate-900 via-teal-800 to-slate-800 bg-clip-text text-transparent">MedScan</h1>
                       <div className="w-2.5 h-2.5 bg-rose-500 rounded-full animate-heartbeat shadow-[0_0_12px_rgba(244,63,94,0.6)]"></div>
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-slate-400 ml-0.5 mt-1.5 opacity-60">AI Health Companion</p>
               </div>
               <div className="flex space-x-3">
                   <button onClick={() => setCurrentView(AppView.INFO)} className="w-11 h-11 bg-white flex items-center justify-center rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-50 text-slate-400 hover:text-teal-600 transition-all active:scale-90">
                       <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                   </button>
                   <button onClick={() => setCurrentView(AppView.PROFILE)} className={`w-11 h-11 flex items-center justify-center rounded-2xl transition-all active:scale-90 ${isPremium ? 'bg-gradient-to-br from-amber-400 to-orange-500 shadow-xl shadow-amber-200' : 'bg-white border border-slate-100 shadow-xl shadow-slate-200/50'}`}>
                       <svg className={`w-6 h-6 ${isPremium ? 'text-white' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                   </button>
               </div>
            </header>

            {healthTip && (
                 <div className="mb-10 p-6 bg-white border border-teal-50/50 rounded-[2.5rem] flex items-start shadow-2xl shadow-teal-900/5 animate-slide-up hover:shadow-teal-900/10 transition-shadow">
                    <div className="w-12 h-12 bg-teal-50 rounded-2xl flex items-center justify-center mr-4 shrink-0 text-2xl shadow-inner">💊</div>
                    <div>
                        <h4 className="text-[10px] font-black text-teal-600/70 uppercase tracking-widest mb-1.5">Smart Tip</h4>
                        <span className="text-sm text-slate-700 font-bold leading-relaxed">{healthTip}</span>
                    </div>
                 </div>
            )}

            <Scanner onScanComplete={handleScanComplete} onError={(msg) => alert(msg)} />

            {!isPremium && (
                <div onClick={() => setShowPremiumModal(true)} className="mt-10 bg-slate-900 text-white p-7 rounded-[3rem] shadow-2xl shadow-slate-900/20 flex justify-between items-center cursor-pointer transform transition-all hover:translate-y-[-2px] active:scale-95 group relative overflow-hidden border border-slate-800">
                    <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-900 z-0"></div>
                    <div className="absolute -top-12 -right-12 w-48 h-48 bg-white opacity-[0.05] rounded-full blur-3xl group-hover:opacity-10 transition-opacity"></div>
                    <div className="relative z-10">
                        <h3 className="font-extrabold text-xl flex items-center tracking-tight">Expert Insights <span className="ml-2">💎</span></h3>
                        <p className="text-[10px] text-slate-500 mt-1 font-black uppercase tracking-widest opacity-80">Unlock Detailed Safety Reports</p>
                    </div>
                    <div className="relative z-10 bg-white text-slate-900 px-6 py-3 rounded-2xl font-black text-xs shadow-xl tracking-widest uppercase">₹99</div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return <Reminders reminders={reminders} addReminder={addReminder} deleteReminder={deleteReminder} toggleReminder={toggleReminder} />;
      case AppView.INFO:
          return <LegalAndHelp />;
      case AppView.PROFILE:
          return <Profile isPremium={isPremium} />;
      default:
        return <div className="p-10 text-center">View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative shadow-2xl overflow-hidden font-sans text-slate-800">
      <main className="min-h-screen relative z-10 overflow-y-auto hide-scrollbar">
        {renderContent()}
      </main>
      {!scannedData && (
        <nav className="fixed bottom-8 left-8 right-8 max-w-[calc(28rem-4rem)] mx-auto glass rounded-[2.5rem] shadow-2xl shadow-slate-300/40 px-3 py-4 flex justify-around items-center z-40 border border-white/80">
            {[
                { view: AppView.HOME, icon: "M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z M15 13a3 3 0 11-6 0 3 3 0 016 0z", label: "Scan" },
                { view: AppView.REMINDERS, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "Alarms" },
                { view: AppView.PROFILE, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: isPremium ? "Profile" : "Pro" }
            ].map((item) => {
                const isActive = currentView === item.view || (item.view === AppView.HOME && currentView === AppView.SCANNER);
                return (
                    <button key={item.label} onClick={() => (item.view === AppView.PROFILE && !isPremium) ? setShowPremiumModal(true) : setCurrentView(item.view)} className={`flex flex-col items-center justify-center w-16 h-14 rounded-2xl transition-all duration-500 ${isActive ? 'bg-slate-900 text-white shadow-2xl shadow-slate-900/30' : 'text-slate-400 hover:text-slate-600'}`}>
                        <svg className={`w-6 h-6 mb-1 ${isActive ? 'stroke-2' : 'stroke-[1.5]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d={item.icon} /></svg>
                        <span className={`text-[9px] font-black tracking-widest uppercase ${isActive ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
                    </button>
                );
            })}
        </nav>
      )}
      <PremiumModal isOpen={showPremiumModal} onClose={() => setShowPremiumModal(false)} onUpgrade={handleUpgrade} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData, PatientProfile, AgeGroup, Gender, Language } from '../types';

interface ScannerProps {
  onScanComplete: (data: MedicineData, profile: PatientProfile) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ onScanComplete, onError }) => {
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [qualityWarning, setQualityWarning] = useState<string | null>(null);

  const [ageGroup, setAgeGroup] = useState<AgeGroup>('adult');
  const [gender, setGender] = useState<Gender>('male');
  const [isPregnant, setIsPregnant] = useState(false);
  const [isBreastfeeding, setIsBreastfeeding] = useState(false);
  const [language, setLanguage] = useState<Language>('english');

  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const triggerCamera = () => cameraInputRef.current?.click();
  const triggerGallery = () => galleryInputRef.current?.click();

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => { setImagePreview(reader.result as string); setShowForm(true); };
    reader.readAsDataURL(file);
  }, []);

  const startAnalysis = async () => {
    if (!imagePreview) return;
    setShowForm(false);
    setAnalyzing(true);
    try {
      const profile = { ageGroup, gender, isPregnant, isBreastfeeding, language };
      const data = await analyzeMedicineImage(imagePreview, profile);
      onScanComplete(data, profile);
    } catch (err) {
      onError("Scan failed. Ensure the text is clear and try again.");
      setImagePreview(null);
    } finally {
      setAnalyzing(false);
    }
  };

  if (showForm && imagePreview) {
      return (
          <div className="w-full max-w-md mx-auto bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-slide-up relative z-50 border border-slate-100 mb-20">
              <div className="h-80 relative group">
                  <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/40 to-transparent flex flex-col justify-end p-8">
                      <h3 className="text-white font-black text-3xl tracking-tighter mb-1">Set Profile</h3>
                      <p className="text-slate-300 text-[10px] font-black uppercase tracking-[0.3em] opacity-80">Verify patient details for safety</p>
                  </div>
              </div>
              <div className="p-8 space-y-8 bg-white">
                   <div className="space-y-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Language</label>
                      <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
                          {(['english', 'hindi', 'hinglish'] as Language[]).map(l => (
                              <button key={l} onClick={() => setLanguage(l)} className={`flex-1 py-3 rounded-xl text-xs font-black capitalize transition-all duration-300 ${language === l ? 'bg-white text-teal-700 shadow-xl shadow-slate-200' : 'text-slate-400 hover:text-slate-600'}`}>{l}</button>
                          ))}
                      </div>
                  </div>
                  <div className="space-y-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Age Category</label>
                      <div className="grid grid-cols-3 gap-3">
                          {[ { id: 'child', emoji: '👶', label: 'Child' }, { id: 'adult', emoji: '🧑', label: 'Adult' }, { id: 'senior', emoji: '👴', label: 'Senior' } ].map((item) => (
                             <button key={item.id} onClick={() => setAgeGroup(item.id as AgeGroup)} className={`py-5 rounded-3xl border transition-all duration-500 active:scale-90 ${ageGroup === item.id ? 'border-teal-500 bg-teal-50 text-teal-900 ring-4 ring-teal-500/10' : 'border-slate-100 bg-white text-slate-500 hover:bg-slate-50'}`}>
                                <span className="block text-3xl mb-1">{item.emoji}</span>
                                <span className="text-[9px] font-black uppercase tracking-widest">{item.label}</span>
                            </button>
                          ))}
                      </div>
                  </div>
                  <div className="space-y-3">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Gender</label>
                      <div className="grid grid-cols-2 gap-4">
                          <button onClick={() => { setGender('male'); setIsPregnant(false); setIsBreastfeeding(false); }} className={`py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${gender === 'male' ? 'bg-blue-600 text-white shadow-2xl shadow-blue-500/30' : 'bg-slate-50 text-slate-400 border border-slate-100'}`}>Male</button>
                          <button onClick={() => setGender('female')} className={`py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${gender === 'female' ? 'bg-rose-500 text-white shadow-2xl shadow-rose-500/30' : 'bg-slate-50 text-slate-400 border border-slate-100'}`}>Female</button>
                      </div>
                  </div>
                  {gender === 'female' && (
                      <div className="bg-rose-50 p-6 rounded-[2.5rem] space-y-4 border border-rose-100 animate-fade-in">
                          {[ { label: "Pregnant 🤰", state: isPregnant, setter: setIsPregnant }, { label: "Breastfeeding 🤱", state: isBreastfeeding, setter: setIsBreastfeeding } ].map((item, i) => (
                              <label key={i} className="flex items-center space-x-4 cursor-pointer group select-none">
                                  <div className={`w-7 h-7 rounded-xl border-2 flex items-center justify-center transition-all ${item.state ? 'bg-rose-500 border-rose-500' : 'bg-white border-rose-200'}`}>
                                      {item.state && <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>}
                                  </div>
                                  <input type="checkbox" checked={item.state} onChange={(e) => item.setter(e.target.checked)} className="hidden" />
                                  <span className="text-slate-800 font-black text-[11px] uppercase tracking-wide">{item.label}</span>
                              </label>
                          ))}
                      </div>
                  )}
                  <div className="pt-4 space-y-3">
                    <button onClick={startAnalysis} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-slate-900/30 hover:translate-y-[-2px] active:scale-95 transition-all flex items-center justify-center space-x-4">
                        <span>Analyze Medicine</span>
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                    </button>
                    <button onClick={() => { setImagePreview(null); setShowForm(false); }} className="w-full text-center py-4 text-slate-400 font-black text-[10px] hover:text-slate-700 transition-colors uppercase tracking-[0.2em]">Discard & Retake</button>
                  </div>
              </div>
          </div>
      )
  }

  return (
    <div className="flex flex-col items-center w-full">
      <input type="file" accept="image/*" capture="environment" ref={cameraInputRef} onChange={handleFileChange} className="hidden" />
      <input type="file" accept="image/*" ref={galleryInputRef} onChange={handleFileChange} className="hidden" />

      {analyzing ? (
        <div className="text-center p-12 bg-white rounded-[4rem] shadow-2xl w-full max-w-sm mx-4 relative overflow-hidden mt-10 border border-slate-50">
            <div className="absolute top-0 left-0 w-full h-2.5 bg-gradient-to-r from-teal-400 via-emerald-500 to-teal-400 animate-[shimmer_2s_infinite]"></div>
            <div className="relative w-40 h-40 mx-auto mb-10">
                {imagePreview && <img src={imagePreview} alt="Scanning" className="w-full h-full object-cover rounded-full border-[10px] border-white shadow-2xl relative z-10" />}
                <div className="absolute -inset-3 rounded-full border-[5px] border-teal-500 border-t-transparent animate-spin z-20"></div>
                <div className="absolute -inset-8 rounded-full border-2 border-teal-100/50 animate-pulse-soft z-0"></div>
            </div>
            <h3 className="text-4xl font-black text-slate-900 mb-3 tracking-tighter">Analyzing...</h3>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.3em] mb-10 opacity-70">Cross-referencing Global Databases</p>
            <div className="h-1.5 w-32 bg-slate-50 rounded-full mx-auto overflow-hidden">
                <div className="h-full bg-teal-500 w-1/2 animate-[shimmer_2s_infinite]"></div>
            </div>
        </div>
      ) : (
        <div className="w-full space-y-8 animate-slide-up">
           {/* Primary HERO Action */}
           <button onClick={triggerCamera} className="group relative w-full h-72 rounded-[4rem] overflow-hidden shadow-2xl shadow-teal-900/30 transition-all duration-500 hover:scale-[1.03] active:scale-95 border-4 border-white">
              <div className="absolute inset-0 bg-gradient-to-br from-teal-600 via-emerald-600 to-teal-800 transition-colors group-hover:from-teal-700 group-hover:to-teal-800"></div>

              {/* Animated Scanner Beam Effect */}
              <div className="animate-scan z-20"></div>

              <div className="absolute -top-12 -right-12 w-64 h-64 bg-white/10 rounded-full blur-[80px] group-hover:scale-125 transition-transform duration-1000"></div>
              <div className="absolute bottom-0 left-0 w-48 h-48 bg-black/10 rounded-full blur-[80px]"></div>

              <div className="absolute inset-0 flex flex-col items-center justify-center text-white z-30 px-6 text-center">
                  <div className="w-24 h-24 bg-white/20 backdrop-blur-2xl rounded-[2.5rem] flex items-center justify-center mb-6 group-hover:rotate-[12deg] group-hover:scale-110 transition-all duration-500 border border-white/40 shadow-2xl animate-pulse-soft">
                       <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </div>
                  <h3 className="text-4xl font-black tracking-tighter mb-2">Scan Medicine</h3>
                  <p className="text-teal-100/80 font-black text-[11px] tracking-[0.4em] uppercase">Box • Strip • Prescription</p>
              </div>
           </button>

           {/* Secondary ACTION */}
           <button onClick={triggerGallery} className="w-full glass py-7 px-8 rounded-[3rem] font-black shadow-xl shadow-slate-200/50 flex items-center justify-between hover:bg-white transition-all active:scale-95 group border border-white">
             <div className="flex items-center">
                 <div className="w-16 h-16 bg-white text-indigo-600 rounded-[1.8rem] flex items-center justify-center mr-6 group-hover:scale-110 transition-transform shadow-lg border border-indigo-50">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                 </div>
                 <div className="text-left">
                    <span className="block text-slate-900 text-2xl font-black tracking-tighter leading-none mb-1">Gallery Import</span>
                    <span className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] opacity-80">Choose from photos</span>
                 </div>
             </div>
             <div className="w-11 h-11 rounded-full bg-slate-100/50 flex items-center justify-center group-hover:bg-slate-900 group-hover:text-white transition-all duration-300">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
             </div>
           </button>

           {/* Trust Footnote */}
           <div className="flex justify-center space-x-10 pt-8 opacity-30">
               <div className="flex flex-col items-center">
                   <div className="w-1.5 h-1.5 bg-slate-900 rounded-full mb-3"></div>
                   <span className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-800">Secure AI</span>
               </div>
               <div className="flex flex-col items-center">
                   <div className="w-1.5 h-1.5 bg-slate-900 rounded-full mb-3"></div>
                   <span className="text-[9px] font-black uppercase tracking-[0.3em] text-slate-800">Private Lab</span>
               </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Scanner;

import React, { useState } from 'react';
import { Reminder, FoodContext, RepeatType, SoundType, VoiceTone } from '../types';

interface RemindersProps {
  reminders: Reminder[];
  addReminder: (r: Reminder) => void;
  deleteReminder: (id: string) => void;
  toggleReminder: (id: string) => void;
}

const Reminders: React.FC<RemindersProps> = ({ reminders, addReminder, deleteReminder, toggleReminder }) => {
  const [showForm, setShowForm] = useState(false);
  const [name, setName] = useState('');
  const [dose, setDose] = useState('');
  const [time, setTime] = useState('');
  const [foodContext, setFoodContext] = useState<FoodContext>('after_food');
  const [repeat, setRepeat] = useState<RepeatType>('daily');
  const [customDays, setCustomDays] = useState<number[]>([]); 
  const [soundType, setSoundType] = useState<SoundType>('ringtone');
  const [voiceTone, setVoiceTone] = useState<VoiceTone>('normal');

  const previewSound = (type: SoundType, tone?: VoiceTone) => {
      window.speechSynthesis.cancel();
      if (type === 'voice') {
          let text = tone === 'strict' ? "Medicine now." : tone === 'friendly' ? "Hey, it's time!" : tone === 'hindi' ? "Dawai ka time ho gaya." : "Take your medicine.";
          const u = new SpeechSynthesisUtterance(text);
          if (tone === 'hindi') u.lang = 'hi-IN';
          window.speechSynthesis.speak(u);
      } else {
           try {
               const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
               const osc = ctx.createOscillator();
               const gain = ctx.createGain();
               osc.connect(gain); gain.connect(ctx.destination);

               if (type === 'soft') { osc.type = 'sine'; osc.frequency.setValueAtTime(350, ctx.currentTime); }
               else if (type === 'loud') { osc.type = 'square'; osc.frequency.setValueAtTime(600, ctx.currentTime); }
               else if (type === 'zen') { osc.type = 'sine'; osc.frequency.setValueAtTime(200, ctx.currentTime); osc.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.5); }
               else if (type === 'emergency') { osc.type = 'sawtooth'; osc.frequency.setValueAtTime(1200, ctx.currentTime); osc.frequency.setValueAtTime(400, ctx.currentTime + 0.1); }
               else if (type === 'musical') { osc.type = 'triangle'; osc.frequency.setValueAtTime(523.25, ctx.currentTime); osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.15); osc.frequency.setValueAtTime(783.99, ctx.currentTime + 0.3); }
               else if (type === 'ringtone') { 
                   osc.type = 'sine'; 
                   osc.frequency.setValueAtTime(440, ctx.currentTime); 
                   osc.frequency.setValueAtTime(480, ctx.currentTime + 0.1); 
                   osc.frequency.setValueAtTime(0, ctx.currentTime + 0.2); 
                   osc.frequency.setValueAtTime(440, ctx.currentTime + 0.3); 
               }
               else { osc.type = 'square'; osc.frequency.setValueAtTime(440, ctx.currentTime); }

               osc.start(); osc.stop(ctx.currentTime + 0.6);
           } catch (e) {}
      }
  };

  const handleSoundSelect = (type: SoundType) => { setSoundType(type); previewSound(type, voiceTone); };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !time || !dose) return;
    addReminder({ id: Date.now().toString(), medicineName: name, dose, time, foodContext, repeat, customDays, soundType, voiceTone: soundType === 'voice' ? voiceTone : undefined, active: true, snoozedUntil: null, createdAt: Date.now() });
    setShowForm(false); setName(''); setDose(''); setTime('');
  };

  return (
    <div className="p-8 pb-40 animate-fade-in max-w-lg mx-auto">
      <div className="flex justify-between items-end mb-12">
        <div>
            <h2 className="text-4xl font-extrabold text-slate-900 tracking-tighter">My Alarms</h2>
            <p className="text-teal-600 text-[10px] font-black uppercase tracking-[0.4em] mt-2 opacity-60">Precision Schedule</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className="bg-slate-900 text-white w-14 h-14 rounded-3xl shadow-2xl flex items-center justify-center hover:scale-110 active:scale-90 transition-all border border-slate-700">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-[3.5rem] shadow-2xl border border-slate-100 mb-12 space-y-10 animate-slide-up relative z-10">
            <h3 className="text-xl font-black text-slate-900 flex items-center tracking-tight">
                <span className="w-3 h-3 bg-teal-500 rounded-full mr-4 shadow-teal-200 shadow-lg"></span> 
                New Schedule
            </h3>

            <div className="grid grid-cols-2 gap-6">
                <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Medicine</label>
                    <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Advil" required className="w-full p-5 bg-slate-50 rounded-2xl border-none font-bold text-slate-800 placeholder-slate-300 focus:ring-4 focus:ring-teal-500/10 transition-all" />
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Quantity</label>
                    <input type="text" value={dose} onChange={(e) => setDose(e.target.value)} placeholder="1 pill" required className="w-full p-5 bg-slate-50 rounded-2xl border-none font-bold text-slate-800 placeholder-slate-300 focus:ring-4 focus:ring-teal-500/10 transition-all" />
                </div>
            </div>

            <div className="grid grid-cols-2 gap-6">
                <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Exact Time</label>
                    <input type="time" value={time} onChange={(e) => setTime(e.target.value)} required className="w-full p-5 bg-slate-50 rounded-2xl border-none font-black text-2xl text-teal-700 shadow-inner" />
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Intake Rule</label>
                    <select value={foodContext} onChange={(e) => setFoodContext(e.target.value as FoodContext)} className="w-full p-5 bg-slate-50 rounded-2xl border-none font-bold text-xs text-slate-700 focus:ring-4 focus:ring-teal-500/10 transition-all">
                        <option value="after_food">After Food 🥣</option>
                        <option value="before_food">Before Food 🍎</option>
                        <option value="empty_stomach">Empty Stomach 🚫</option>
                        <option value="any">Anytime 🤷</option>
                    </select>
                </div>
            </div>

            <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">AI Sound Experience</label>
                <div className="grid grid-cols-4 gap-2.5">
                     {(['ringtone', 'musical', 'zen', 'emergency', 'soft', 'loud', 'default', 'voice'] as SoundType[]).map(s => (
                         <button key={s} type="button" onClick={() => handleSoundSelect(s)} className={`py-3.5 text-[9px] font-black rounded-2xl border transition-all uppercase tracking-tighter active:scale-90 ${soundType === s ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-900/30' : 'border-slate-100 text-slate-400 bg-white hover:bg-slate-50'}`}>{s}</button>
                     ))}
                </div>
                {soundType === 'voice' && (
                    <div className="bg-teal-50/50 p-5 rounded-3xl flex space-x-2 border border-teal-100/50 animate-fade-in">
                         {(['normal', 'strict', 'friendly', 'hindi'] as VoiceTone[]).map(t => (
                             <button key={t} type="button" onClick={() => { setVoiceTone(t); previewSound('voice', t); }} className={`flex-1 py-3 text-[10px] font-black rounded-xl capitalize border transition-all ${voiceTone === t ? 'bg-white text-teal-700 border-teal-200 shadow-md' : 'text-slate-400 border-transparent hover:text-slate-600'}`}>{t}</button>
                         ))}
                    </div>
                )}
            </div>

            <div className="pt-6 flex space-x-4">
                <button type="button" onClick={() => setShowForm(false)} className="flex-1 bg-slate-100 text-slate-500 py-6 rounded-[2.5rem] font-black text-[11px] uppercase tracking-widest hover:bg-slate-200 transition-colors">Dismiss</button>
                <button type="submit" className="flex-[2] bg-teal-600 text-white py-6 rounded-[2.5rem] font-black text-sm uppercase tracking-widest shadow-2xl shadow-teal-600/30 hover:translate-y-[-2px] active:scale-95 transition-all">Enable Alarm</button>
            </div>
        </form>
      )}

      <div className="space-y-8">
            {reminders.map(rem => (
                <div key={rem.id} className={`p-8 rounded-[3.5rem] border transition-all duration-500 relative overflow-hidden group ${rem.active ? 'bg-white border-white shadow-2xl shadow-slate-200/50' : 'bg-slate-50 border-transparent opacity-40 grayscale blur-[0.5px]'}`}>
                    <div className="flex justify-between items-center relative z-10">
                        <div className="flex items-center space-x-8">
                            <div className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center shadow-2xl transition-all duration-500 ${rem.active ? 'bg-slate-900 text-white scale-100' : 'bg-slate-200 text-slate-500'}`}>
                                <span className="text-2xl font-black tracking-tighter leading-none">{rem.time}</span>
                                <span className="text-[9px] uppercase font-black tracking-widest mt-1 opacity-60">{rem.repeat}</span>
                            </div>
                            <div>
                                <h3 className={`font-black text-2xl tracking-tighter leading-none mb-2 ${rem.active ? 'text-slate-900' : 'text-slate-500'}`}>{rem.medicineName}</h3>
                                <div className="flex items-center space-x-3">
                                    <span className="text-[10px] font-black text-white bg-teal-600 px-3 py-1.5 rounded-xl uppercase tracking-widest shadow-md">{rem.dose}</span>
                                    <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest opacity-70 italic">{rem.foodContext.replace('_', ' ')}</span>
                                </div>
                            </div>
                        </div>
                        <div className="flex flex-col space-y-4">
                            <button onClick={() => toggleReminder(rem.id)} className={`w-14 h-7 rounded-full p-1.5 transition-all duration-500 shadow-inner ${rem.active ? 'bg-teal-500' : 'bg-slate-300'}`}>
                                <div className={`bg-white w-4 h-4 rounded-full shadow-2xl transform transition-transform duration-500 ${rem.active ? 'translate-x-7' : ''}`}></div>
                            </button>
                            <button onClick={() => deleteReminder(rem.id)} className="w-14 h-10 rounded-2xl bg-rose-50 text-rose-300 flex items-center justify-center hover:bg-rose-500 hover:text-white transition-all active:scale-90 border border-rose-100/50">
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            </button>
                        </div>
                    </div>
                </div>
            ))}
            {reminders.length === 0 && !showForm && (
                <div className="text-center py-32 animate-fade-in opacity-40">
                    <div className="w-32 h-32 bg-white rounded-[3.5rem] flex items-center justify-center mx-auto mb-8 text-slate-100 shadow-xl border border-slate-50">
                        <svg className="w-14 h-14 text-slate-200" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </div>
                    <h3 className="text-slate-900 font-black text-2xl tracking-tighter">No Active Alarms</h3>
                    <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-2">Time for your first med?</p>
                </div>
            )}
      </div>
    </div>
  );
};

export default Reminders;
